window.CHAPTERS=window.CHAPTERS||{};window.CHAPTERS["bc12"]={"id":"bc12","title":"12. 核酸的物理化学性质和研究方法","sub":"朱圣庚《生物化学》第4版 · 第12章","sub2":"第12章 · 全量PPT/笔记页 + 本页考点 + 课后题","modules":[{"i":0,"name":"第12章 核酸的物理化学性质和研究方法","slides":[{"i":0,"sec":"老师PPT逐页","title":"第12章 核酸的物理化学性质和研究方法","notes":"这是全章的总起页，统领核酸的水解、酸碱解离与紫外吸收、变性复性与杂交，以及凝胶电泳、限制酶、印迹杂交等研究方法。学习时应把“化学结构决定理化性质、理化性质又决定研究手段”这条主线贯穿始终。","points":["全章分水解、酸碱性质、紫外吸收、变性复性杂交四大块","研究方法包括核酸酶、限制性内切酶、电泳与印迹杂交","核心逻辑：结构→理化性质→实验方法","注意本章与核酸化学结构章节的前后衔接"],"fig":"","page":null,"anim":null,"img":"assets/img/bc12/full1.jpg","imageExplain":"标题页无数据图，重点记住章节标题与后续四节的排列顺序，据此建立全章知识框架。","srcType":"老师PPT","role":"主线","check":{"kind":"mcq","id":"bc12_check_0","q":"本章标题为“核酸的物理化学性质”，下列哪一项不属于本章的核心内容？","a":"D","e":"本章围绕核酸的水解、酸碱解离、紫外吸收以及变性/复性/杂交展开；糖酵解属于糖代谢，与核酸的物理化学性质无关。","src":"本页自测","o":["A. 核酸的水解","B. 碱基解离与紫外吸收","C. 变性、复性与杂交","D. 糖酵解途径"],"oe":["A错误：核酸的水解是本章第一节内容。","B错误：碱基解离与紫外吸收分别是本章第二、三节内容。","C错误：变性、复性与杂交是本章第四节内容。","D正确：糖酵解是葡萄糖分解代谢途径，不属于本章核酸物理化学性质的内容。"]}},{"i":1,"sec":"老师PPT逐页","title":"第一节 核酸的水解","notes":"本节讨论核酸在水、酸、碱和酶作用下逐步降解的规律。需要分清化学水解（酸、碱）与酶促水解在断键位置、产物末端上的差别，这是理解后续测序与核酸酶应用的基础。","points":["水解本质是断裂3′,5′-磷酸二酯键","酸水解、碱水解、酶水解三条路径","不同水解方式得到不同末端（3′-P或5′-P）","为核酸酶分类和序列分析做铺垫"],"fig":"","page":null,"anim":null,"img":"assets/img/bc12/full2.jpg","imageExplain":"小节页只有标题，留意“水解”一词指向磷酸二酯键的断裂，而非糖苷键或碱基内部键。","srcType":"老师PPT","role":"主线","check":{"kind":"mcq","id":"bc12_check_1","q":"核酸水解成核苷酸时，主要断裂的化学键是？","a":"A","e":"核酸是由核苷酸通过3′,5′-磷酸二酯键连接成的多聚核苷酸，降解为核苷酸时断裂的是磷酸二酯键。","src":"本页自测","o":["A. 磷酸二酯键","B. 肽键","C. 二硫键","D. 糖苷键"],"oe":["A正确：磷酸二酯键连接相邻核苷酸，是核酸水解成核苷酸时断裂的键。","B错误：肽键存在于蛋白质中，不存在于核酸主链。","C错误：二硫键主要维持蛋白质空间结构。","D错误：糖苷键连接碱基与戊糖，断裂它得到的是核苷而非核苷酸。"]}},{"i":2,"sec":"老师PPT逐页","title":"核酸的逐步水解","notes":"核酸先水解为核苷酸，核苷酸再脱去磷酸生成核苷，核苷进一步断裂糖苷键得到戊糖和碱基。完全水解的终产物是磷酸、戊糖和碱基，这一降解层级是理解核酸组成分析的依据。","points":["核酸→核苷酸→核苷→戊糖+碱基","核酸到核苷酸断的是磷酸二酯键","核苷酸到核苷断的是磷酸酯键","核苷到碱基断的是N-糖苷键","完全水解终产物：磷酸、戊糖、碱基"],"fig":"","page":null,"anim":null,"img":"assets/img/bc12/full3.jpg","srcType":"老师PPT","role":"主线","check":{"kind":"fill","id":"bc12_check_2","q":"核酸逐步水解的最终产物是磷酸、戊糖和____。","a":"碱基","e":"核酸→核苷酸→磷酸+核苷→戊糖+碱基；因此完全水解的终产物为磷酸、戊糖和碱基。","src":"本页自测"},"imageExplain":"沿流程图从上到下看每一级箭头，确认每步脱去的是磷酸还是碱基，并注意磷酸二酯键与糖苷键分属不同层级。"},{"i":3,"sec":"老师PPT逐页","title":"酸水解的特点","notes":"酸既能水解磷酸酯键，也能水解糖苷键，但糖苷键比磷酸酯键更易被酸断裂。嘌呤碱的糖苷键又比嘧啶碱的糖苷键对酸更不稳定，所以稀酸处理会优先脱去嘌呤，生成无嘌呤核酸（AP位点）。","points":["酸可同时水解糖苷键和磷酸酯键","糖苷键对酸比磷酸酯键更敏感","嘌呤糖苷键比嘧啶糖苷键更易酸解","稀酸易造成脱嘌呤，形成AP位点"],"fig":"","page":null,"anim":null,"img":"assets/img/bc12/full4.jpg","srcType":"老师PPT","role":"主线","check":{"kind":"mcq","id":"bc12_check_3","q":"关于核酸的酸水解，下列叙述正确的是？","a":"A","e":"酸水解可同时作用于糖苷键和磷酸酯键，其中糖苷键更易断裂；嘌呤糖苷键又比嘧啶糖苷键更不稳定，故酸水解易造成脱嘌呤。","src":"本页自测","o":["A. 糖苷键和磷酸酯键都能被酸水解，且糖苷键比磷酸酯键更易被酸水解","B. 只有磷酸酯键能被酸水解，糖苷键完全不受影响","C. 嘌呤碱的糖苷键比嘧啶碱的糖苷键对酸更稳定","D. 酸水解首先断裂戊糖与磷酸之间的酯键，碱基不脱落"],"oe":["A正确：糖苷键与磷酸酯键均可被酸水解，且糖苷键更易断裂。","B错误：糖苷键同样可被酸水解，并非不受影响。","C错误：嘌呤碱的糖苷键对酸更不稳定，而非更稳定。","D错误：酸水解优先断裂糖苷键，易脱嘌呤，并非先断磷酸酯键。"]},"imageExplain":"看图中被酸进攻的两个位置，比较糖苷键与磷酸酯键的断裂难易，并留意嘌呤与嘧啶糖苷键稳定性的差异标注。"},{"i":4,"sec":"老师PPT逐页","title":"碱水解的特点","notes":"RNA的磷酸二酯键易被碱水解，而DNA对碱稳定。原因是RNA核糖2′-OH在碱性条件下作为亲核基团进攻相邻磷酸，先形成2′,3′-环磷酸，再开环生成2′-或3′-磷酸核苷；DNA脱氧核糖缺少2′-OH，无法进行这一分子内进攻。","points":["RNA磷酸二酯键易被碱水解","DNA对碱稳定，缺少2′-OH","机制：2′-OH进攻磷酸生成2′,3′-环磷酸","开环产物为2′-或3′-磷酸核苷","碱水解可用于去除RNA、纯化DNA"],"fig":"","page":null,"anim":null,"img":"assets/img/bc12/full5.jpg","srcType":"老师PPT","role":"主线","check":{"kind":"judge","id":"bc12_check_4","q":"RNA的磷酸酯键易被碱水解，而DNA对碱稳定。","a":"对","e":"RNA核糖具有2′-OH，碱水解时可参与形成2′,3′-环磷酸中间体，使磷酸二酯键易断裂；DNA为脱氧核糖，缺少2′-OH，因而对碱较稳定。","src":"本页自测"},"imageExplain":"注意图中核糖2′-OH指向磷酸的箭头，这是RNA碱敏、DNA碱稳的结构根源，并标出环磷酸中间体。"},{"i":5,"sec":"老师PPT逐页","title":"水解方式小结与过渡","notes":"本页承上启下，把酸水解、碱水解的结果汇总后转入酶促水解。需要记住化学水解条件剧烈、选择性有限，而酶水解专一性高、条件温和，更适合精确研究核酸结构。","points":["酸水解偏向脱嘌呤、断糖苷键","碱水解专一降解RNA","化学水解剧烈、选择性差","酶水解温和、专一性强","由此过渡到核酸酶的分类"],"fig":"","page":null,"anim":null,"img":"assets/img/bc12/full6.jpg","imageExplain":"过渡页用于比较三种水解路径的断键位置与产物末端，为下一页核酸酶分类建立对照。","srcType":"老师PPT","role":"主线","check":{"kind":"short","id":"bc12_check_5","q":"核酸水解按所用试剂可分为哪三类？","a":"酸水解、碱水解和酶水解。","e":"这是核酸水解的三种基本方式；酶水解中起作用的酶统称核酸酶，可再按底物和作用方式细分。","src":"本页自测"}},{"i":6,"sec":"老师PPT逐页","title":"酶水解与核酸酶分类","notes":"专一水解核酸磷酸二酯键的酶统称核酸酶（nuclease）。按底物专一性分为只作用于RNA的RNase和只作用于DNA的DNase；按作用方式分为从链内部切断的核酸内切酶和从链末端逐个切除的核酸外切酶，也有兼具两种活性的酶。","points":["核酸酶专一水解磷酸二酯键","按底物分：RNase作用于RNA，DNase作用于DNA","按方式分：内切酶切内部，外切酶切末端","存在内外切活性兼有的核酸酶","酶水解专一、温和，是研究核酸的利器"],"fig":"","page":null,"anim":null,"img":"assets/img/bc12/full7.jpg","srcType":"老师PPT","role":"主线","check":{"kind":"mcq","id":"bc12_check_6","q":"按对底物作用的方式分类，核酸酶可分为？","a":"A","e":"按作用方式分为核酸内切酶（切链内部）和核酸外切酶（从末端逐个切），有的酶兼具两种作用。","src":"本页自测","o":["A. 核酸内切酶和核酸外切酶","B. RNase和DNase","C. 酸水解酶和碱水解酶","D. 限制酶和连接酶"],"oe":["A正确：内切酶作用于链内部，外切酶从末端水解，这是按作用方式的分类。","B错误：RNase和DNase是按底物专一性分类。","C错误：核酸酶并无“酸水解酶/碱水解酶”这种分类。","D错误：限制酶是内切酶的一种，连接酶不是水解酶。"]},"imageExplain":"对照图中“内切”与“外切”示意，内切酶在链中部断键、外切酶从3′或5′端逐一切下核苷酸。"},{"i":7,"sec":"老师PPT逐页","title":"磷酸二酯键的两种断裂方式","notes":"磷酸二酯键可在3′-OH与磷酸基之间断裂，也可在5′-OH与磷酸基之间断裂。前者在断点留下3′-OH、另一侧留下5′-磷酸；后者留下5′-OH、另一侧留下3′-磷酸，不同的断键方式决定了产物的末端类型。","points":["断裂方式一：3′-OH与磷酸之间断","断裂方式二：5′-OH与磷酸之间断","产物可为3′-P末端或5′-P末端","末端类型影响后续连接与测序","不同核酸酶偏好不同断键位置"],"fig":"","page":null,"anim":null,"img":"assets/img/bc12/full8.jpg","srcType":"老师PPT","role":"主线","check":{"kind":"mcq","id":"bc12_check_7","q":"按磷酸二酯键断裂方式，核酸酶可使键在哪些位置断裂？","a":"A","e":"磷酸二酯键的断裂可发生在3′-O—P处或5′-O—P处，分别产生带有3′-磷酸或5′-磷酸末端的产物。","src":"本页自测","o":["A. 在3′-OH与磷酸基之间，或在5′-OH与磷酸基之间","B. 只在碱基与戊糖之间","C. 只在两个碱基之间","D. 只在戊糖的2′-OH与3′-OH之间"],"oe":["A正确：断裂可位于3′-OH与磷酸之间，或5′-OH与磷酸之间。","B错误：碱基与戊糖之间是糖苷键，不是磷酸二酯键的断裂位置。","C错误：碱基之间没有共价键直接相连。","D错误：2′-OH与3′-OH之间不是磷酸二酯键的骨架位置。"]},"imageExplain":"看图中箭头落在3′-O–P还是5′-O–P键上，据此判断产物是3′-磷酸还是5′-磷酸末端。"},{"i":8,"sec":"老师PPT逐页","title":"RNase A（牛胰核糖核酸酶）","notes":"牛胰核糖核酸酶简称RNase I或RNase A，只水解RNA而不作用于DNA，且十分耐热。它是专一性极高的内切酶，作用于嘧啶核苷-3′-磷酸与其下游核苷酸之间的连键，产物为3′-磷酸嘧啶核苷酸。","points":["别名RNase I / RNase A，来自牛胰","只作用于RNA，不作用于DNA","耐热，专一性极高的内切酶","切点在嘧啶-3′-磷酸的3′侧","产物为3′-磷酸嘧啶核苷酸"],"fig":"","page":null,"anim":null,"img":"assets/img/bc12/full9.jpg","srcType":"老师PPT","role":"主线","check":{"kind":"mcq","id":"bc12_check_8","q":"牛胰核糖核酸酶（RNase A）的作用位点和主要产物是？","a":"A","e":"RNase A是高度专一的核酸内切酶，只作用于RNA，作用点为嘧啶核苷-3′-磷酸与相邻核苷酸之间的连键，产物为3′-磷酸嘧啶核苷酸，且十分耐热。","src":"本页自测","o":["A. 切割嘧啶核苷-3′-磷酸与相邻核苷酸之间的连键，产物为3′-磷酸嘧啶核苷酸","B. 切割嘌呤核苷-5′-磷酸连键，产物为5′-磷酸嘌呤核苷酸","C. 切割任意碱基之间的连键，产物为平末端","D. 只水解DNA，产物为3′-磷酸脱氧核苷酸"],"oe":["A正确：RNase A专一切割嘧啶核苷-3′-磷酸侧的连键，生成3′-磷酸嘧啶核苷酸。","B错误：RNase A不专一作用于嘌呤核苷-5′-磷酸。","C错误：它并非切割任意碱基，且不产生平末端。","D错误：RNase A只作用于RNA，不作用于DNA。"]},"imageExplain":"在RNA链上找到嘧啶碱基，注意RNase A在其3′-磷酸与下一个核苷酸之间下刀，产物带3′-磷酸。"},{"i":9,"sec":"老师PPT逐页","title":"DNase I 与 DNase II","notes":"牛胰DNase I是内切酶，可切断双链或单链DNA，产物为5′-磷酸末端的寡聚核苷酸，需要Mg²⁺（或Mn²⁺、Co²⁺），最适pH 7–8。牛脾DNase II则生成3′-磷酸末端寡聚核苷酸，最适pH 4–5，需0.3 mol/L Na⁺激活，Mg²⁺反而抑制。","points":["DNase I：牛胰，产物为5′-磷酸末端","DNase I需Mg²⁺/Mn²⁺/Co²⁺，最适pH 7–8","DNase II：牛脾，产物为3′-磷酸末端","DNase II最适pH 4–5，需Na⁺激活","Mg²⁺抑制DNase II"],"fig":"","page":null,"anim":null,"img":"assets/img/bc12/full10.jpg","srcType":"老师PPT","role":"主线","check":{"kind":"mcq","id":"bc12_check_9","q":"下列关于牛胰脱氧核糖核酸酶（DNase I）的叙述，正确的是？","a":"A","e":"DNase I是内切酶，可切断双链或单链DNA，生成以5′-磷酸为末端的寡聚核苷酸，需Mg2+（或Mn2+、Co2+），最适pH 7～8。","src":"本页自测","o":["A. 切割双链或单链DNA，产生5′-磷酸末端寡核苷酸，需Mg2+，最适pH 7～8","B. 切割DNA产生3′-磷酸末端，最适pH 4～5","C. 需要0.3 mol/L Na+激活，且被Mg2+抑制","D. 只能作用于单链RNA"],"oe":["A正确：DNase I产生5′-磷酸末端，依赖Mg2+，最适pH 7～8。","B错误：产生3′-磷酸末端、最适pH 4～5的是DNase II（牛脾）。","C错误：需0.3 mol/L Na+激活且被Mg2+抑制的是DNase II。","D错误：DNase I作用于DNA，不作用于RNA。"]},"imageExplain":"对比两种酶产物的末端标记：DNase I留下5′-P，DNase II留下3′-P，并注意最适pH与激活离子的差别。"},{"i":10,"sec":"老师PPT逐页","title":"限制性内切酶","notes":"限制性核酸内切酶能识别双链DNA中的特定核苷酸序列，并在此切割双链，主要从原核生物中分离纯化。它是原核生物限制-修饰防御系统的一部分，也是分子克隆和基因工程的核心工具；仅Ⅱ型酶在1994年就已发现2300种以上。","points":["识别双链DNA特定序列并切割","主要来源于原核生物","属于限制-修饰防御系统","Ⅱ型酶是分子克隆的常用工具","种类极多，1994年Ⅱ型已超2300种"],"fig":"","page":null,"anim":null,"img":"assets/img/bc12/full11.jpg","srcType":"老师PPT","role":"主线","check":{"kind":"mcq","id":"bc12_check_10","q":"限制性核酸内切酶主要来源于哪类生物？","a":"A","e":"限制性核酸内切酶能识别双链DNA的特定核苷酸序列并在该处切割，主要从原核生物中分离纯化，是原核生物限制-修饰系统的一部分。","src":"本页自测","o":["A. 原核生物","B. 真核生物细胞核","C. 线粒体","D. 内质网"],"oe":["A正确：限制酶主要从原核生物中分离得到。","B错误：它们并非主要来源于真核细胞核。","C错误：线粒体不是限制酶的主要来源。","D错误：内质网与限制酶的来源无关。"]},"imageExplain":"图中强调酶在双链DNA的特定识别序列处切断，而非随机降解，注意“识别序列”与“切割位点”两个概念。"},{"i":11,"sec":"老师PPT逐页","title":"限制-修饰系统的发现","notes":"20世纪中期，Arber等人研究λ噬菌体在大肠杆菌不同菌株平板上的培养效应，发现原核生物体内存在受寄主控制的限制与修饰系统。限制作用降解外源DNA，修饰作用（甲基化）保护自身DNA不被切割。","points":["Arber等以λ噬菌体在不同大肠杆菌菌株上的培养为模型","发现寄主控制的限制与修饰系统","限制作用切割外源DNA","修饰作用通过甲基化保护自身DNA","这是限制性内切酶发现的历史起点"],"fig":"","page":null,"anim":null,"img":"assets/img/bc12/full12.jpg","srcType":"老师PPT","role":"主线","check":{"kind":"judge","id":"bc12_check_11","q":"Arber等人以λ噬菌体在大肠杆菌不同菌株上的平板培养效应为基础，发现了原核生物的限制和修饰系统。","a":"对","e":"这正是限制性内切酶发现史上的重要实验依据：同一噬菌体在不同大肠杆菌菌株上的感染能力不同，揭示了寄主控制的限制与修饰现象。","src":"本页自测"},"imageExplain":"关注λ噬菌体在不同大肠杆菌菌株上形成噬菌斑数量的差异，这种“菌株依赖性”正是限制-修饰系统的证据。"},{"i":12,"sec":"老师PPT逐页","title":"限制酶的类型（Ⅰ、Ⅱ、Ⅲ型）","notes":"Ⅰ型酶是单一多功能酶，具3种不同亚基，限制与修饰活性合为一体；Ⅱ型酶的限制性内切酶与甲基化酶是分开的，蛋白为单一成分；Ⅲ型酶是具共同亚基的双功能酶，含2种不同亚基。分子克隆主要使用Ⅱ型酶。","points":["Ⅰ型：单一多功能酶，3种亚基","Ⅱ型：内切酶与甲基化酶分开，单一成分","Ⅲ型：双功能酶，2种亚基","Ⅱ型切割位点明确，最适于克隆","类型划分依据亚基组成与酶活性组织方式"],"fig":"","page":null,"anim":null,"img":"assets/img/bc12/full13.jpg","srcType":"老师PPT","role":"主线","check":{"kind":"mcq","id":"bc12_check_12","q":"Ⅱ型核酸内切限制酶在“限制和修饰活性”及“蛋白质结构”上的特点是？","a":"A","e":"Ⅱ型酶的限制性内切酶与甲基化酶是分开的两种活性，蛋白质为单一成分；Ⅰ型为单一多功能酶、3种不同亚基，Ⅲ型为具共同亚基的双功能酶、2种不同亚基。","src":"本页自测","o":["A. 核酸内切酶和甲基化酶分开，为单一成分","B. 单一的多功能酶，含3种不同亚基","C. 具有共同亚基的双功能酶，含2种不同亚基","D. 只有甲基化活性，不含内切酶活性"],"oe":["A正确：Ⅱ型酶的内切酶与甲基化酶分开，蛋白为单一成分。","B错误：单一多功能酶、3种亚基是Ⅰ型酶的特点。","C错误：具共同亚基的双功能酶、2种亚基是Ⅲ型酶的特点。","D错误：Ⅱ型酶同时具有限制性内切酶活性（与甲基化酶分开）。"]},"imageExplain":"按表格三列逐行比较Ⅰ、Ⅱ、Ⅲ型在“限制与修饰活性”和“蛋白质结构”上的差异，重点记住Ⅱ型是单一成分、双酶分开。"},{"i":13,"sec":"老师PPT逐页","title":"三型限制酶的切割位点与用途","notes":"Ⅰ型酶在距特异性位点至少1000 bp处随机切割，无序列特异性，克隆中基本无用；Ⅱ型酶在识别位点处或其附近切割，序列特异，克隆中十分有用；Ⅲ型酶在距识别位点3′端24–26 bp处切割，用处不大。三型都能识别未甲基化序列并切割。","points":["Ⅰ型：距识别位点≥1000 bp随机切割","Ⅱ型：识别位点处或附近切割，序列特异","Ⅲ型：距识别位点3′端24–26 bp切割","Ⅱ型在DNA克隆中最有用","Ⅰ型无序列特异性，Ⅲ型用处不大"],"fig":"","page":null,"anim":null,"img":"assets/img/bc12/full14.jpg","srcType":"老师PPT","role":"主线","check":{"kind":"mcq","id":"bc12_check_13","q":"Ⅰ型核酸内切限制酶的切割位点特点是？","a":"A","e":"Ⅰ型酶在距特异性位点至少1000 bp处随机切割，序列特异性差，在DNA克隆中基本无用；Ⅱ型酶在识别位点内或附近切割，Ⅲ型酶在距位点3′端24～26 bp处切割。","src":"本页自测","o":["A. 在距特异性识别位点至少1000 bp处可能随机切割","B. 严格在识别序列内部定点切割","C. 在距特异性位点3′端24～26 bp处切割","D. 不切割DNA，只催化甲基化"],"oe":["A正确：Ⅰ型酶远离识别位点（≥1000 bp）随机切割。","B错误：在位点内或附近定点切割是Ⅱ型酶的特点。","C错误：3′端24～26 bp处切割是Ⅲ型酶的特点。","D错误：Ⅰ型酶具有内切酶活性，并非只做甲基化。"]},"imageExplain":"对照表格的“切割位点”和“DNA克隆中的用处”两行，理解切割的序列特异性如何决定其克隆价值。"},{"i":14,"sec":"老师PPT逐页","title":"Ⅱ型限制酶的三个基本特性","notes":"Ⅱ型酶在双链DNA的特异性识别序列处切割并产生链断裂；两条单链的断裂位点通常不直接相对，而是错开；因此断裂后形成的DNA片段带有互补的单链延伸末端（黏性末端）。","points":["在特异性识别序列处切割双链","两条单链断点通常彼此错开、不直接相对","错开切割产生互补的单链延伸末端","黏性末端便于片段互补配对与连接","这是Ⅱ型酶适用于克隆的结构基础"],"fig":"","page":null,"anim":null,"img":"assets/img/bc12/full15.jpg","srcType":"老师PPT","role":"主线","check":{"kind":"mcq","id":"bc12_check_14","q":"Ⅱ型核酸限制性内切酶切割DNA后，断裂片段通常具有什么特征？","a":"A","e":"Ⅱ型酶在特异性识别序列处切割双链，两个单链断裂部位通常不直接相对，因此产生互补的单链延伸末端，即黏性末端。","src":"本页自测","o":["A. 具有互补的单链延伸末端（黏性末端）","B. 一定形成平末端","C. 只产生单链断裂而不产生双链断裂","D. 末端均为3′-OH且无磷酸"],"oe":["A正确：两条链的切口错开，形成互补单链延伸末端。","B错误：并非一定为平末端，例如EcoRV才产生平末端。","C错误：Ⅱ型酶切割双链DNA，产生双链断裂。","D错误：末端磷酸化状态取决于切口位置，不能一概而论。"]},"imageExplain":"看图中两条链的切口是否对齐：错开的切口在片段两端留下可互补配对的单链突出，即黏性末端。"},{"i":15,"sec":"老师PPT逐页","title":"识别位点的回文结构","notes":"Ⅱ型酶识别的序列通常由4–8个核苷酸组成，具有双重旋转对称性，即两条链上按5′→3′读出的序列相同，呈回文结构。例如EcoRI识别GAATTC，其互补链按5′→3′也是GAATTC。","points":["识别序列长4–8个核苷酸","具有双重旋转对称（回文）结构","两条链5′→3′读序相同","典型例子：EcoRI识别GAATTC","回文结构使两条链可被同一酶对称切割"],"fig":"","page":null,"anim":null,"img":"assets/img/bc12/full16.jpg","srcType":"老师PPT","role":"主线","check":{"kind":"mcq","id":"bc12_check_15","q":"Ⅱ型限制酶识别的核苷酸序列通常具有什么结构特点？","a":"A","e":"Ⅱ型酶识别4～8个核苷酸的特定序列，其切割位点的共同特点是具有双重旋转对称结构，即核苷酸顺序呈回文结构。","src":"本页自测","o":["A. 由4～8个核苷酸组成，呈双重旋转对称（回文）结构","B. 由1～2个核苷酸组成，无对称性","C. 必须是单链RNA序列","D. 富含尿嘧啶的随机序列"],"oe":["A正确：识别序列为4～8个核苷酸且呈回文/双重旋转对称。","B错误：识别序列并非只有1～2个核苷酸，且有对称性。","C错误：限制酶识别双链DNA，不是单链RNA。","D错误：识别序列有特定对称性，并非富含U的随机序列。"]},"imageExplain":"把识别序列两条链都按5′→3′方向读一遍，确认读出相同的回文序列，并注意对称轴位置。"},{"i":16,"sec":"老师PPT逐页","title":"PstⅠ、EcoRⅠ与EcoRⅤ的切割产物","notes":"PstⅠ识别CTGCAG，在A与G之间切割，产生3′-OH突出的黏性末端；EcoRⅠ识别GAATTC，在G与A之间切割，产生5′-磷酸突出的黏性末端；EcoRⅤ识别GATATC，在AT之间平切，产生平末端。黏性末端利于互补连接，平末端连接效率较低。","points":["PstⅠ：CTGCAG，产生3′-OH黏性末端","EcoRⅠ：GAATTC，产生5′-P黏性末端","EcoRⅤ：GATATC，产生平末端","黏性末端由错开切割形成","平末端连接效率低于黏性末端"],"fig":"","page":null,"anim":null,"img":"assets/img/bc12/full17.jpg","srcType":"老师PPT","role":"主线","check":{"kind":"mcq","id":"bc12_check_16","q":"EcoRI识别5′-GAATTC-3′并在G与A之间切割，切割后形成的末端是？","a":"A","e":"EcoRI切割后形成5′-P的单链黏性末端；PstI切割形成3′-OH黏性末端，EcoRV切割则形成平末端。","src":"本页自测","o":["A. 带5′-磷酸的黏性末端","B. 带3′-OH的黏性末端","C. 平末端","D. 带3′-磷酸的黏性末端"],"oe":["A正确：EcoRI的切口产生5′-磷酸突出的黏性末端。","B错误：3′-OH黏性末端是PstI切割的产物。","C错误：EcoRV才产生平末端。","D错误：EcoRI产生的是5′-磷酸末端，而非3′-磷酸末端。"]},"imageExplain":"逐一核对三个酶的识别序列与切口位置，比较PstⅠ、EcoRⅠ的错开切口和EcoRⅤ的平齐切口。"},{"i":17,"sec":"老师PPT逐页","title":"限制酶的命名规则","notes":"命名取属名首字母加种名前两个字母组成三字母略语，如Escherichia coli记为Eco、Haemophilus influenzae记为Hin；菌株或型用下标字母表示；同一菌株有多个限制-修饰系统时用罗马数字区分，如HindⅠ、HindⅡ、HindⅢ。","points":["属名首字母+种名前两字母=三字母略语","Eco来自Escherichia coli，Hin来自Haemophilus influenzae","菌株/型用下标字母标注","多个系统用罗马数字区分（Ⅰ、Ⅱ、Ⅲ）","例：HindⅢ=流感嗜血菌Rd株第3个系统"],"fig":"","page":null,"anim":null,"img":"assets/img/bc12/full18.jpg","srcType":"老师PPT","role":"主线","check":{"kind":"mcq","id":"bc12_check_17","q":"限制酶名称HindⅢ中，“Hin”部分代表？","a":"A","e":"命名时用属名首字母和种名前两个字母组成3字母略语：Haemophilus influenzae→Hin；随后的d代表菌株Rd，Ⅲ表示该菌株的第3套限制-修饰体系。","src":"本页自测","o":["A. 流感嗜血菌（Haemophilus influenzae）","B. 大肠杆菌（Escherichia coli）","C. 人（Homo sapiens）","D. 一种限制酶基因"],"oe":["A正确：Hin来自Haemophilus influenzae（流感嗜血菌）。","B错误：大肠杆菌的略语是Eco。","C错误：人不是该命名所指的寄主菌。","D错误：Hin表示寄主菌物种名，不是基因名。"]},"imageExplain":"把EcoRⅠ拆成Eco（菌种）+R（菌株）+Ⅰ（序号）三段来读，理解每个字母的来源。"},{"i":18,"sec":"老师PPT逐页","title":"腺嘌呤的解离与pKa","notes":"腺嘌呤的N1可结合质子，pK₁′约为4.15；中性形式在N9失去质子，pK₂′约为9.8，生成带负电的阴离子。这说明嘌呤碱基的质子化与带电状态随pH改变，是核酸酸碱性质的化学基础。","points":["N1质子化，pK₁′≈4.15","N9去质子，pK₂′≈9.8","低pH带正电，高pH带负电","碱基带电状态随pH变化","为核苷酸两性解离打基础"],"fig":"","page":null,"anim":null,"img":"assets/img/bc12/full19.jpg","imageExplain":"在腺嘌呤结构上找到N1和N9，对照两个pKa标出哪个氮在酸性下获质子、哪个在碱性下失质子。","srcType":"老师PPT","role":"主线","check":{"kind":"mcq","id":"bc12_check_18","q":"腺嘌呤N1质子化pK1′≈4.15，N9失质子pK2′≈9.8。在pH 7.0时，腺嘌呤主要的存在形式是？","a":"A","e":"pH 7.0高于pK1′（4.15）而低于pK2′（9.8）：N1已去质子化、N9仍保持质子化，故净电荷约为0，以中性形式为主。","src":"本页自测","o":["A. 中性分子","B. 带正电荷的阳离子","C. 带负电荷的阴离子","D. 同时带正负电荷的两性离子"],"oe":["A正确：在4.15与9.8之间，腺嘌呤以中性形式为主。","B错误：pH明显高于pK1′，N1不会主要保持质子化带正电。","C错误：pH低于pK2′，N9尚未大量失质子，不会主要带负电。","D错误：此pH下没有同时稳定的正、负电荷中心。"]}},{"i":19,"sec":"老师PPT逐页","title":"碱基的解离","notes":"核酸的碱基、核苷和核苷酸都能发生解离，核酸的酸碱性质即源于此。嘧啶和嘌呤杂环上的氮以及各取代基既能结合质子也能释放质子，因此这些物质同时具有碱性解离和酸性解离的两性特征。","points":["碱基、核苷、核苷酸均可解离","杂环氮可结合质子（碱性）","取代基可释放质子（酸性）","整体表现为两性电解质","核酸酸碱性质由此而来"],"fig":"","page":null,"anim":null,"img":"assets/img/bc12/full20.jpg","srcType":"老师PPT","role":"主线","check":{"kind":"fill","id":"bc12_check_19","q":"核酸的碱基、核苷和核苷酸均能发生解离，是因为杂环中的氮及各取代基既能结合又能释放____。","a":"质子","e":"嘌呤和嘧啶杂环中的氮原子及各取代基具有结合和释放质子的能力，因此这些物质既有碱性解离又有酸性解离。","src":"本页自测"},"imageExplain":"注意图中标出的环氮与取代基两类可解离基团，一类结合H⁺、一类释放H⁺，共同构成两性行为。"},{"i":20,"sec":"老师PPT逐页","title":"胞嘧啶的解离","notes":"胞嘧啶环上的氮原子有一对未共用电子，可结合质子而显碱性（N3质子化，pKa约4.2）；环上的烯醇式羟基类似酚羟基，能释放质子而显酸性（pKa约12.2）。因此胞嘧啶既有碱性解离又有酸性解离。","points":["环氮未共用电子对可结合质子","N3质子化pKa约4.2，显碱性","烯醇式羟基类似酚羟基可释质子","酸性解离pKa约12.2","胞嘧啶为典型两性碱基"],"fig":"","page":null,"anim":null,"img":"assets/img/bc12/full21.jpg","srcType":"老师PPT","role":"主线","check":{"kind":"mcq","id":"bc12_check_20","q":"胞嘧啶的酸性解离主要来自哪个基团？","a":"A","e":"胞嘧啶环上氮原子有未共用电子对，可结合质子而显碱性；其烯醇式羟基与酚羟基相似，能释放质子而显酸性。","src":"本页自测","o":["A. 烯醇式羟基（性质类似酚羟基）释放质子","B. 环上氮原子结合质子","C. 磷酸基释放质子","D. 戊糖的2′-OH释放质子"],"oe":["A正确：酸性来自烯醇式羟基释放质子。","B错误：环氮结合质子体现的是碱性，不是酸性来源。","C错误：胞嘧啶碱基本身不含磷酸基。","D错误：戊糖2′-OH不是胞嘧啶酸性解离的主要基团。"]},"imageExplain":"在胞嘧啶结构上分别指出N3（得质子）和烯醇羟基（失质子）两个解离位点，对应一碱一酸两步解离。"},{"i":21,"sec":"老师PPT逐页","title":"磷酸二酯键的水解产物","notes":"水进攻磷酸二酯键可得到两种产物：一种在3′位带磷酸、2′位为游离OH（3′-PO₄产物），另一种在2′位带磷酸、3′位为游离OH（2′-PO₄产物）。RNA中2′-OH参与形成2′,3′-环磷酸中间体，因此水解常得到2′-和3′-磷酸的混合物。","points":["水解断裂磷酸二酯键","可生成3′-PO₄产物（2′-OH游离）","可生成2′-PO₄产物（3′-OH游离）","RNA经2′,3′-环磷酸中间体","产物常为2′-与3′-磷酸核苷混合物"],"fig":"","page":null,"anim":null,"img":"assets/img/bc12/full22.jpg","imageExplain":"看图中磷酸基连接在核糖的2′还是3′位，据此区分2′-PO₄与3′-PO₄两种产物及游离OH的位置。","srcType":"老师PPT","role":"主线","check":{"kind":"mcq","id":"bc12_check_21","q":"水进攻磷酸二酯键后，可能生成的两种产物是？","a":"A","e":"磷酸二酯键水解时水分子进攻磷原子，断键位置不同可得到3′-PO4产物（2′-OH游离）或2′-PO4产物（3′-OH游离）。","src":"本页自测","o":["A. 3′-磷酸产物（3′带磷酸、2′-OH）和2′-磷酸产物（2′带磷酸、3′-OH）","B. 5′-磷酸产物和1′-磷酸产物","C. 只生成3′-磷酸产物","D. 只生成游离碱基和戊糖"],"oe":["A正确：可分别形成3′-磷酸产物与2′-磷酸产物，并伴有游离OH。","B错误：水解产物不是5′-磷酸与1′-磷酸的组合。","C错误：并非只生成3′-磷酸产物，也可能生成2′-磷酸产物。","D错误：游离碱基和戊糖是进一步完全水解的产物，不是磷酸二酯键水解的直接产物。"]}},{"i":22,"sec":"老师PPT逐页","title":"核苷酸的解离与等电点","notes":"核苷酸同时含磷酸基和碱基，是两性电解质，在不同pH下解离程度不同，一定条件下可形成兼性离子（两性离子）。当带负电的磷酸基数目与带正电的含氮环数目相等时，所在pH即为等电点，pI=(pK₁′+pK₂′)/2；pK₁′对应第一磷酸基的解离，pK₂′对应含氮环=N⁺H的解离。","points":["核苷酸含磷酸与碱基，为两性电解质","可形成兼性（两性）离子","正负电荷相等时pH即等电点","pI=(pK₁′+pK₂′)/2","pK₁′为磷酸基解离，pK₂′为含氮环解离"],"fig":"","page":null,"anim":null,"img":"assets/img/bc12/full23.jpg","srcType":"老师PPT","role":"主线","check":{"kind":"mcq","id":"bc12_check_22","q":"某核苷酸第一磷酸基的pK1′=1.0，含氮环N+H的pK2′=6.0。按pI=(pK1′+pK2′)/2计算，其等电点约为？","a":"A","e":"pI=(1.0+6.0)/2=3.5。在等电点时，带负电的磷酸基数目与带正电的含氮环数目相等，分子呈兼性离子。","src":"本页自测","o":["A. 3.5","B. 6.0","C. 7.0","D. 1.0"],"oe":["A正确：pI=(1.0+6.0)/2=3.5。","B错误：6.0只是pK2′，不是两pKa的平均值。","C错误：中性pH不等于该核苷酸的等电点。","D错误：1.0只是pK1′，不能单独作为pI。"]},"imageExplain":"看图中随pH变化各基团的带电符号，找到正负电荷恰好抵消、净电荷为零的那一点，即等电点。"},{"i":23,"sec":"老师PPT逐页","title":"第三节 核酸的紫外吸收","notes":"本节解释核酸为什么在260 nm有特征吸收，以及如何利用A260/A280比值和摩尔磷吸光系数进行定量、纯度判断和变性监测。学习时要抓住“共轭双键→紫外吸收→增色/减色效应”的因果链。","points":["碱基共轭双键是紫外吸收的结构基础","最大吸收在260 nm附近","A260/A280用于判断纯度","ε(P)用于定量与变性监测","增色/减色效应反映双螺旋状态"],"fig":"","page":null,"anim":null,"img":"assets/img/bc12/full24.jpg","imageExplain":"小节页只有标题，先建立“共轭双键决定260 nm吸收”的预期，再看后续曲线与比值数据。","srcType":"老师PPT","role":"主线","check":{"kind":"mcq","id":"bc12_check_23","q":"测定核酸含量和纯度时，紫外分光光度法常用的吸收波长是？","a":"A","e":"嘌呤和嘧啶的共轭双键使碱基、核苷、核苷酸和核酸在240～290 nm有强吸收，最大吸收值在260 nm附近，故用A260定量。","src":"本页自测","o":["A. 260 nm","B. 280 nm","C. 320 nm","D. 220 nm"],"oe":["A正确：核酸的最大紫外吸收在260 nm附近。","B错误：280 nm主要反映蛋白质（芳香族氨基酸）的吸收。","C错误：320 nm不是核酸的特征吸收峰。","D错误：220 nm附近受肽键等干扰，不用于核酸定量。"]}},{"i":24,"sec":"老师PPT逐页","title":"核酸紫外吸收的原理","notes":"嘌呤碱和嘧啶碱具有共轭双键，使碱基、核苷、核苷酸和核酸在240–290 nm紫外波段有强吸收，最大吸收值在260 nm附近。不同核苷酸的吸收特性不同，因此可用紫外分光光度计进行定量和定性测定。","points":["碱基共轭双键产生紫外吸收","吸收波段240–290 nm","最大吸收峰约260 nm","不同核苷酸吸收特性不同","可用紫外分光光度计定量、定性"],"fig":"","page":null,"anim":null,"img":"assets/img/bc12/full25.jpg","srcType":"老师PPT","role":"主线","check":{"kind":"mcq","id":"bc12_check_24","q":"核酸在260 nm附近产生强烈紫外吸收的结构基础是？","a":"A","e":"嘌呤与嘧啶具有共轭双键体系，能强烈吸收240～290 nm紫外光，最大吸收约在260 nm；不同核苷酸吸收特性不同，可用于定性定量。","src":"本页自测","o":["A. 嘌呤碱和嘧啶碱中的共轭双键","B. 磷酸基的P=O键","C. 戊糖的羟基","D. 碱基对之间的氢键"],"oe":["A正确：共轭双键是核酸紫外吸收的结构基础。","B错误：磷酸基不是260 nm强吸收的主要来源。","C错误：戊糖羟基不产生该特征吸收峰。","D错误：氢键本身不造成260 nm的强吸收。"]},"imageExplain":"看吸收光谱曲线的峰值位置，确认最大吸收落在260 nm，并注意整个吸收带覆盖240–290 nm。"},{"i":25,"sec":"老师PPT逐页","title":"A260/A280判断纯度与含量","notes":"由A260/A280比值可判断核酸样品纯度：纯DNA应大于1.8，纯RNA应达到2.0，比值偏低通常提示蛋白质污染。对纯样品，读出A260即可估算含量：1 A₂₆₀相当于50 µg/mL双链DNA、40 µg/mL单链DNA或RNA、20 µg/mL寡核苷酸。","points":["A260/A280判断纯度","纯DNA比值>1.8，纯RNA≈2.0","比值偏低提示蛋白质污染","1 A₂₆₀=50 µg/mL双链DNA","1 A₂₆₀=40 µg/mL单链DNA/RNA，20 µg/mL寡核苷酸"],"fig":"","page":null,"anim":null,"img":"assets/img/bc12/full26.jpg","srcType":"老师PPT","role":"主线","check":{"kind":"mcq","id":"bc12_check_25","q":"某双链DNA溶液稀释10倍后测得A260=0.25。按1 A260≈50 μg/mL双链DNA计算，原液DNA浓度约为？","a":"A","e":"稀释液浓度=0.25×50=12.5 μg/mL，再乘稀释倍数10，原液约为125 μg/mL。纯DNA的A260/A280应大于1.8。","src":"本页自测","o":["A. 125 μg/mL","B. 12.5 μg/mL","C. 50 μg/mL","D. 500 μg/mL"],"oe":["A正确：0.25×50×10=125 μg/mL。","B错误：12.5 μg/mL是稀释后浓度，漏乘了稀释倍数。","C错误：50 μg/mL是A260=1时的浓度，未按实测值换算。","D错误：500 μg/mL计算有误（多乘了10）。"]},"imageExplain":"对照比值标准：DNA>1.8、RNA≈2.0，再记住不同核酸形态下1个A₂₆₀对应的微克数。"},{"i":26,"sec":"老师PPT逐页","title":"电泳结合溴化乙锭估算含量","notes":"对于不纯的核酸样品，可先用琼脂糖凝胶电泳按分子大小分离出区带，再用溴化乙锭染色，在紫外灯下观察荧光强度粗略估计含量。溴化乙锭嵌入双链核酸后荧光显著增强，灵敏度高但具有毒性。","points":["不纯样品先用琼脂糖凝胶电泳分离","按分子大小形成不同区带","溴化乙锭染色后在紫外灯下观察","荧光强度可粗略估计含量","溴化乙锭为嵌入型荧光染料，有毒"],"fig":"","page":null,"anim":null,"img":"assets/img/bc12/full27.jpg","srcType":"老师PPT","role":"主线","check":{"kind":"mcq","id":"bc12_check_26","q":"对不纯的核酸样品进行琼脂糖凝胶电泳后，常用哪种染料在紫外灯下显示核酸区带？","a":"A","e":"溴化乙锭可嵌入核酸双链并在紫外灯下发出荧光，用于琼脂糖凝胶电泳后粗略估计核酸区带的含量。","src":"本页自测","o":["A. 溴化乙锭","B. 考马斯亮蓝","C. 茚三酮","D. 苏丹红"],"oe":["A正确：溴化乙锭染色后可在紫外灯下观察核酸区带。","B错误：考马斯亮蓝用于蛋白质染色。","C错误：茚三酮用于氨基酸显色。","D错误：苏丹红用于脂类染色。"]},"imageExplain":"看凝胶泳道中的荧光条带，条带越亮表示该大小片段含量越高，可对照已知量marker粗略定量。"},{"i":27,"sec":"老师PPT逐页","title":"摩尔磷吸光系数与增色/减色效应","notes":"核酸紫外吸收常用摩尔磷吸光系数表示：ε(P)=A/(c·l)。天然DNA的ε(P)约为6600，RNA约为7700–7800，单链多核苷酸的ε(P)高于双螺旋结构。变性时ε(P)升高称增色效应，原因是双螺旋中碱基对π电子云重叠减少了对紫外光的吸收；复性后ε(P)降低称减色效应，故可用ε(P)判断DNA是否变性或降解。","points":["ε(P)=A/(c·l)，以摩尔磷为单位","天然DNA ε(P)≈6600，RNA≈7700–7800","单链ε(P)高于双螺旋","变性ε(P)升高=增色效应","复性ε(P)降低=减色效应，可判断变性/降解"],"fig":"","page":null,"anim":null,"img":"assets/img/bc12/full28.jpg","srcType":"老师PPT","role":"主线","check":{"kind":"mcq","id":"bc12_check_27","q":"天然DNA的摩尔磷吸光系数ε(P)约为6600。若1 cm光径下测得A260=0.66，则核酸磷浓度约为？","a":"A","e":"由ε(P)=A/(c·l)得c=A/(ε·l)=0.66/(6600×1)=1.0×10⁻⁴ mol/L。核酸变性时ε(P)升高（增色效应），复性后降低（减色效应）。","src":"本页自测","o":["A. 1.0×10⁻⁴ mol/L","B. 1.0×10⁻³ mol/L","C. 6.6×10⁻⁴ mol/L","D. 1.0×10⁻⁵ mol/L"],"oe":["A正确：c=0.66/6600=1.0×10⁻⁴ mol/L。","B错误：数量级算错，应为10⁻⁴而非10⁻³。","C错误：6.6×10⁻⁴是对公式错误变形得到的。","D错误：数量级偏小一个数量级。"]},"imageExplain":"比较双螺旋与单链状态下的吸收值：双螺旋因碱基π电子云重叠而吸收较低，解链后吸收升高即增色效应。"},{"i":28,"sec":"老师PPT逐页","title":"第四节 核酸的变性、复性及杂交","notes":"本节讨论双螺旋在热、酸碱或化学试剂作用下解链（变性），以及条件恢复后重新配对（复性），并在此基础上引出不同来源核酸的杂交。核心概念是Tm、Cot½以及Southern/Northern/Western印迹。","points":["变性是氢键断裂、双链变单链","Tm反映双螺旋解链一半时的温度","复性受温度、片段大小、浓度影响","Cot½与基因组大小成正比","杂交衍生出三大印迹技术"],"fig":"","page":null,"anim":null,"img":"assets/img/bc12/full29.jpg","imageExplain":"小节页用于串联“变性→复性→杂交”的逻辑链，注意后续曲线中Tm与Cot½分别描述解链和复性。","srcType":"老师PPT","role":"主线","check":{"kind":"mcq","id":"bc12_check_28","q":"第四节标题所涵盖的三个主题是？","a":"A","e":"第四节为“核酸的变性、复性及杂交”，分别讨论变性机制与Tm、复性动力学（Cot1/2）以及Southern/Northern/Western等杂交技术。","src":"本页自测","o":["A. 变性、复性和杂交","B. 水解、解离和紫外吸收","C. 电泳、离心和层析","D. 复制、转录和翻译"],"oe":["A正确：本节依次讨论变性、复性和杂交。","B错误：水解、解离和紫外吸收属于前三节内容。","C错误：电泳、离心和层析是研究方法，不是本节标题主题。","D错误：复制、转录和翻译属于遗传信息传递，不是本节内容。"]}},{"i":29,"sec":"老师PPT逐页","title":"核酸变性的定义","notes":"变性指核酸双螺旋区的氢键断裂，使双链变成单链，但并不涉及共价键的断裂。因此一级结构（核苷酸序列）保持不变，改变的是空间结构及随之变化的理化性质。","points":["变性断裂的是氢键","双螺旋解为单链","不涉及共价键断裂","一级结构保持不变","理化性质随之改变"],"fig":"","page":null,"anim":null,"img":"assets/img/bc12/full30.jpg","srcType":"老师PPT","role":"主线","check":{"kind":"mcq","id":"bc12_check_29","q":"核酸的变性是指？","a":"A","e":"变性只破坏维持双螺旋的氢键和碱基堆积力，使双链解成单链，共价键（磷酸二酯键、糖苷键）并不断裂，因此不同于降解。","src":"本页自测","o":["A. 双螺旋区的氢键断裂变成单链，但不涉及共价键断裂","B. 磷酸二酯键断裂导致链降解","C. 碱基从戊糖上脱落","D. 糖苷键断裂产生无碱基位点"],"oe":["A正确：变性是氢键断裂、双链解离，不涉及共价键断裂。","B错误：磷酸二酯键断裂属于降解，不是变性。","C错误：碱基脱落是化学损伤/水解，不是变性定义。","D错误：糖苷键断裂也不属于变性。"]},"imageExplain":"看图中双链解开为两条单链，注意碱基间的氢键被破坏而骨架上的磷酸二酯键完好无损。"},{"i":30,"sec":"老师PPT逐页","title":"引起变性的因素","notes":"常见变性因素包括高温（加热到80–100℃）、酸碱度改变以及尿素、甲酰胺等化学试剂。高温破坏氢键，极端pH改变碱基带电状态，尿素和甲酰胺则通过形成氢键竞争性破坏碱基配对。","points":["高温：80–100℃加热变性","酸碱度改变可破坏配对","尿素、甲酰胺等氢键破坏剂","变性因素作用于氢键而非共价键","实验室常用热变性或碱变性"],"fig":"","page":null,"anim":null,"img":"assets/img/bc12/full31.jpg","srcType":"老师PPT","role":"主线","check":{"kind":"mcq","id":"bc12_check_30","q":"下列哪一项不是引起核酸变性的常见因素？","a":"D","e":"常见变性因素包括高温（80～100℃）、极端pH以及尿素、甲醛等化学试剂；适量Mg2+反而有利于中和磷酸电荷、稳定双螺旋。","src":"本页自测","o":["A. 加热到80～100℃","B. 酸碱度改变","C. 加入尿素或甲醛","D. 加入适量Mg2+维持双链"],"oe":["A正确（作为变性因素）：高温是典型变性因素。","B正确（作为变性因素）：酸碱度改变可引起变性。","C正确（作为变性因素）：尿素、甲醛可破坏氢键导致变性。","D错误（符合题意）：适量Mg2+稳定双链，不是变性因素。"]},"imageExplain":"把三类因素对应到双螺旋的氢键上：热、极端pH、尿素/甲酰胺都使碱基对氢键无法维持。"},{"i":31,"sec":"老师PPT逐页","title":"变性的特点与Tm","notes":"变性后紫外吸光度升高、粘度降低、浮力密度升高、酸碱滴定曲线改变。变性发生在一个很窄的温度范围内，通常把加热使DNA双螺旋失去一半时的温度称为熔点或熔解温度Tm，DNA的Tm一般在82–95℃之间。","points":["紫外吸收升高（增色效应）","粘度降低、浮力密度升高","变性发生在很窄的温度范围内","Tm=双螺旋失去一半时的温度","DNA的Tm一般为82–95℃"],"fig":"","page":null,"anim":null,"img":"assets/img/bc12/full32.jpg","srcType":"老师PPT","role":"主线","check":{"kind":"mcq","id":"bc12_check_31","q":"DNA的熔点（Tm）是指？","a":"A","e":"Tm是加热变性使DNA双螺旋结构失去一半（即50%变性）时的温度，一般在82～95℃之间；变性发生在很窄的温度范围内。","src":"本页自测","o":["A. 加热变性使双螺旋结构失去一半时的温度","B. DNA完全变成单链时的温度","C. 变性DNA复性一半时的温度","D. DNA被彻底降解为核苷酸时的温度"],"oe":["A正确：Tm对应50%双螺旋解开的温度。","B错误：完全变性温度高于Tm，不是Tm的定义。","C错误：复性一半对应Cot1/2，不是Tm。","D错误：降解涉及共价键断裂，与Tm无关。"]},"imageExplain":"看熔解曲线：随温度升高A260急剧上升，取吸光值上升到最大值一半处对应的温度即为Tm。"},{"i":32,"sec":"老师PPT逐页","title":"影响Tm值的因素（均一性与GC含量）","notes":"DNA越均一，熔解越集中在一个很窄的温度范围内，曲线越陡。G-C对含量越多，Tm值越高，因为G-C之间有三个氢键，比A-T的两个氢键更稳定，需要更高温度才能解链。","points":["DNA越均一，熔解温度范围越窄","G-C含量越高，Tm越高","G-C有三对氢键，A-T只有两对","GC含量可用来估算Tm","曲线陡峭程度反映样品均一性"],"fig":"","page":null,"anim":null,"img":"assets/img/bc12/full33.jpg","srcType":"老师PPT","role":"主线","check":{"kind":"mcq","id":"bc12_check_32","q":"其他条件相同时，G-C对含量越高的DNA，其Tm值？","a":"A","e":"G-C对之间形成3个氢键，A-T对只有2个氢键，因此G-C含量越高，双螺旋越稳定，解链所需温度越高，Tm越大。","src":"本页自测","o":["A. 越高","B. 越低","C. 不变","D. 先升高后降低"],"oe":["A正确：G-C含量越高，Tm越高。","B错误：G-C含量低才会使Tm偏低。","C错误：碱基组成显著影响Tm，并非不变。","D错误：Tm随G-C含量单调升高，不存在先升后降。"]},"imageExplain":"比较不同GC含量DNA的熔解曲线：GC高者曲线整体右移（Tm高），均一样品曲线更陡。"},{"i":33,"sec":"老师PPT逐页","title":"离子强度对Tm的影响","notes":"介质离子强度较高时，DNA的Tm值较高，且熔解过程发生在较小的温度范围内。原因是阳离子可中和磷酸骨架的负电荷，减少链间静电排斥，使双螺旋更稳定。","points":["离子强度高则Tm高","高离子强度下熔解温度范围更窄","阳离子中和磷酸骨架负电荷","减少链间静电排斥，稳定双螺旋","低盐条件下DNA更易解链"],"fig":"","page":null,"anim":null,"img":"assets/img/bc12/full34.jpg","srcType":"老师PPT","role":"主线","check":{"kind":"judge","id":"bc12_check_33","q":"一般说来，介质离子强度较高时，DNA的Tm值较高，且熔解过程发生在一个较小的温度范围内。","a":"对","e":"较高离子强度可屏蔽磷酸骨架的负电荷，稳定双螺旋，使Tm升高，同时使熔解曲线更陡、熔解温度范围更窄。","src":"本页自测"},"imageExplain":"看不同盐浓度下的熔解曲线：盐浓度越高，曲线右移且更陡，说明Tm升高、转变更集中。"},{"i":34,"sec":"老师PPT逐页","title":"复性的特点","notes":"变性DNA在适当条件下，两条分开的链可重新缔合成双螺旋，这一过程称复性。复性后许多理化性质恢复；但热变性后骤然冷却则不能复性，必须缓慢降温（退火）；片段越大复性越慢，DNA浓度越大复性越快。","points":["复性是两条单链重新缔合成双螺旋","理化性质随之恢复","骤然冷却不能复性，需缓慢退火","片段越大复性越慢","浓度越大复性越快"],"fig":"","page":null,"anim":null,"img":"assets/img/bc12/full35.jpg","srcType":"老师PPT","role":"主线","check":{"kind":"mcq","id":"bc12_check_34","q":"将热变性的DNA骤然冷却，通常会发生什么？","a":"A","e":"复性需要缓慢冷却，使互补链有时间重新配对；骤然冷却时链无法正确配对，通常不能复性。此外片段越大复性越慢，浓度越大复性越快。","src":"本页自测","o":["A. DNA不能复性","B. DNA立即完全复性","C. DNA变性程度进一步加深","D. DNA的Tm显著升高"],"oe":["A正确：骤然冷却使变性DNA不能复性。","B错误：快速冷却阻碍互补链重新缔合，不会立即完全复性。","C错误：骤然冷却不会使变性程度进一步加深。","D错误：冷却过程不改变DNA固有的Tm。"]},"imageExplain":"看复性示意图：缓慢降温时互补单链重新配对成双螺旋，骤然冷却则链仍保持分离状态。"},{"i":35,"sec":"老师PPT逐页","title":"Cot½与基因组大小","notes":"Cot½是衡量复性速度快慢的指标：C₀为变性DNA复性时的初始浓度（以核苷酸摩尔浓度表示），t为时间（秒），Cot½表示复性一半时的Cot值。在DNA浓度相同的情况下，Cot½与基因组大小成正比，基因组越大复性越慢。","points":["Cot½衡量复性速度","C₀为初始核苷酸摩尔浓度","t为时间，单位秒","Cot½为复性一半时的Cot值","浓度相同时Cot½与基因组大小成正比"],"fig":"","page":null,"anim":null,"img":"assets/img/bc12/full36.jpg","srcType":"老师PPT","role":"主线","check":{"kind":"mcq","id":"bc12_check_35","q":"在DNA浓度相同的情况下，Cot1/2与基因组大小的关系是？","a":"A","e":"Cot1/2是复性一半时的Cot值，用于衡量复性速度；在相同DNA浓度下，基因组越大、序列越复杂，复性越慢，Cot1/2越大，二者成正比。","src":"本页自测","o":["A. 与基因组大小成正比","B. 与基因组大小成反比","C. 与基因组大小无关","D. 与基因组大小的平方成正比"],"oe":["A正确：Cot1/2与基因组大小成正比。","B错误：基因组越大复性越慢，Cot1/2越大而非越小。","C错误：Cot1/2正是反映基因组复杂度的指标，并非无关。","D错误：二者是正比关系，不是平方关系。"]},"imageExplain":"看Cot曲线：复性分数达到50%时对应的Cot值即Cot½，曲线越靠右说明基因组越大、复性越慢。"},{"i":36,"sec":"老师PPT逐页","title":"核酸杂交的定义","notes":"把不同来源的DNA放在同一试管中，经热变性后缓慢冷却复性；若异源DNA在某些区域序列相同，复性时就会形成杂交DNA分子。DNA与互补RNA之间也能杂交，这是分子生物学和分子遗传学中应用极广的技术基础。","points":["不同来源DNA热变性后缓慢复性","序列相同区域可形成杂交分子","DNA与互补RNA也能杂交","杂交依赖碱基互补配对","是分子生物学核心技术基础"],"fig":"","page":null,"anim":null,"img":"assets/img/bc12/full37.jpg","srcType":"老师PPT","role":"主线","check":{"kind":"mcq","id":"bc12_check_36","q":"核酸杂交技术的基本原理是？","a":"A","e":"杂交建立在变性-复性基础上：异源DNA经热变性后缓慢冷却，若某些区域序列互补，复性时即形成杂交DNA分子；DNA与互补RNA之间也可杂交。","src":"本页自测","o":["A. 不同来源核酸变性后，互补单链在复性时形成双链杂交分子","B. 抗原与抗体特异性结合","C. 磷酸二酯键被限制酶切割","D. 蛋白质在加热后变性沉淀"],"oe":["A正确：杂交的本质是互补单链复性形成双链。","B错误：抗原-抗体结合是Western blot的检测原理，不是核酸杂交。","C错误：限制酶切割是杂交前的样品处理步骤，不是杂交原理。","D错误：蛋白质变性沉淀与核酸杂交无关。"]},"imageExplain":"看异源双链示意：两条来源不同的链在互补区段配对形成杂交区，非互补区仍保持单链。"},{"i":37,"sec":"老师PPT逐页","title":"常见杂交类型","notes":"常见印迹杂交包括检测DNA的Southern blotting、检测RNA的Northern blotting和检测蛋白质的Western blotting。三者都先把待测分子经电泳分离并转移到膜上，再用探针或抗体识别目标。","points":["Southern blotting检测DNA","Northern blotting检测RNA","Western blotting检测蛋白质","均需电泳分离与转膜","分别用核酸探针或抗体识别"],"fig":"","page":null,"anim":null,"img":"assets/img/bc12/full38.jpg","srcType":"老师PPT","role":"主线","check":{"kind":"mcq","id":"bc12_check_37","q":"用于检测RNA的印迹杂交技术是？","a":"A","e":"三种常见印迹技术中，Southern检测DNA，Northern检测RNA，Western检测蛋白质（用抗体而非核酸探针）。","src":"本页自测","o":["A. Northern blotting","B. Southern blotting","C. Western blotting","D. Eastern blotting"],"oe":["A正确：Northern blotting用于RNA的转膜与杂交检测。","B错误：Southern blotting检测DNA。","C错误：Western blotting检测蛋白质。","D错误：Eastern blotting不是本页所列的常规核酸印迹技术。"]},"imageExplain":"用“DNA-Southern、RNA-Northern、蛋白-Western”一一对应记住三种印迹的检测对象。"},{"i":38,"sec":"老师PPT逐页","title":"Southern印迹杂交","notes":"Southern印迹把电泳凝胶中分离的DNA片段转移并结合到适当滤膜上，再用标记的单链DNA或RNA探针杂交，检测被转移的DNA片段。该方法由E. Southern于1975年首先设计，故称Southern DNA印迹转移技术。","points":["DNA片段从凝胶转移到滤膜","用标记单链DNA/RNA探针杂交","检测膜上的特定DNA片段","E. Southern于1975年建立","是DNA印迹技术的原型"],"fig":"","page":null,"anim":null,"img":"assets/img/bc12/full39.jpg","srcType":"老师PPT","role":"主线","check":{"kind":"mcq","id":"bc12_check_38","q":"Southern印迹杂交主要用于检测哪类分子？","a":"A","e":"Southern印迹由E. Southern于1975年建立：将凝胶中分离的DNA片段转移到滤膜上，再用标记的单链DNA或RNA探针杂交，检测特定DNA片段。","src":"本页自测","o":["A. DNA","B. RNA","C. 蛋白质","D. 脂类"],"oe":["A正确：Southern blot检测DNA片段。","B错误：RNA由Northern blot检测。","C错误：蛋白质由Western blot检测。","D错误：Southern blot不用于检测脂类。"]},"imageExplain":"看“凝胶→滤膜”的转印过程，DNA片段被原样保留在膜上，再用探针与之杂交显示目标条带。"},{"i":39,"sec":"老师PPT逐页","title":"Southern印迹的流程","notes":"标准流程为：限制酶消化DNA→琼脂糖凝胶电泳按大小分离→碱变性并中和→毛细管转印到硝酸纤维素或尼龙膜→标记探针杂交→X射线自显影显示特异片段。碱变性使双链DNA变为单链，便于探针配对；转印使片段位置固定，便于后续杂交。","points":["限制酶消化DNA","琼脂糖凝胶电泳按大小分离","碱变性/中和使DNA成单链","毛细管转印到硝酸纤维素膜","探针杂交后自显影显示特异片段"],"fig":"","page":null,"anim":null,"img":"assets/img/bc12/full40.jpg","imageExplain":"沿流程箭头依次看：酶切、电泳、变性、转膜、杂交、自显影，每一步都为下一步创造条件。","srcType":"老师PPT","role":"主线","check":{"kind":"short","id":"bc12_check_39","q":"简述Southern印迹杂交的主要流程。","a":"限制酶消化DNA→琼脂糖凝胶电泳按大小分离→碱变性/中和→毛细管转印到硝酸纤维素膜→标记探针杂交→X射线自显影，显示特异片段。","e":"该流程先将DNA片段按大小分离，再原位变性并转膜固定，最后用放射性（或标记）探针杂交，通过自显影显示与探针互补的特异片段。","src":"本页自测"}},{"i":40,"sec":"老师PPT逐页","title":"Southern印迹放射自显影结果","notes":"自显影图上A–C泳道约有5.0 kb和4.3 kb两条带，D–F泳道约5.0 kb单带，G–I泳道约3.2 kb单带，J–L泳道约8.5 kb单带。右侧kb标尺用于按迁移距离估读片段大小，迁移越远片段越小。","points":["A–C约5.0与4.3 kb两条带","D–F约5.0 kb单带","G–I约3.2 kb单带","J–L约8.5 kb单带","按右侧kb标尺由迁移距离估读大小"],"fig":"","page":null,"anim":null,"img":"assets/img/bc12/full41.jpg","imageExplain":"把每条带的迁移距离与右侧kb标尺对齐，条带越靠下分子越小，据此读出各组片段大小。","srcType":"老师PPT","role":"主线","check":{"kind":"mcq","id":"bc12_check_40","q":"某Southern印迹放射自显影中，A–C泳道出现约5.0 kb和4.3 kb两条带，D–F泳道仅出现约5.0 kb单带。下列判断正确的是？","a":"B","e":"自显影条带按Kb标尺估读：A–C为5.0和4.3 kb两条带，D–F为5.0 kb单带。同一探针可检出不同大小的片段，双带不必然意味着两种探针。","src":"本页自测","o":["A. A–C与D–F都只含5.0 kb片段","B. A–C除5.0 kb片段外还含约4.3 kb片段，D–F只显5.0 kb片段","C. A–C出现两条带说明使用了两种不同探针","D. D–F的5.0 kb带分子量小于A–C的4.3 kb带"],"oe":["A错误：A–C有5.0和4.3 kb两条带，并非只有5.0 kb。","B正确：A–C为5.0/4.3 kb双带，D–F为5.0 kb单带。","C错误：同一探针可与不同大小的互补片段杂交，双带不能证明用了两种探针。","D错误：5.0 kb片段比4.3 kb片段大，分子量更大、迁移更慢。"]}},{"i":41,"sec":"老师PPT逐页","title":"Northern印迹杂交","notes":"Northern印迹于1979年发展起来，是把RNA分子从电泳凝胶转移到硝酸纤维素滤膜或其他化学修饰的活性滤纸上，再进行核酸杂交的方法。它操作与Southern印迹十分类似，主要用于检测特定RNA的表达与大小。","points":["1979年建立，检测对象为RNA","RNA从凝胶转移到硝酸纤维素膜或活性滤纸","用核酸探针进行杂交","操作与Southern blot类似","用于分析基因表达和RNA大小"],"fig":"","page":null,"anim":null,"img":"assets/img/bc12/full42.jpg","srcType":"老师PPT","role":"主线","check":{"kind":"mcq","id":"bc12_check_41","q":"Northern blotting将RNA从电泳凝胶转移到硝酸纤维素膜或化学修饰活性滤纸上，检测特定RNA主要依靠什么？","a":"A","e":"Northern blotting是RNA印迹杂交：RNA转膜后用互补核酸探针杂交，检测特定RNA。它不使用抗体，抗体检测蛋白属于Western。","src":"本页自测","o":["A. 与互补核酸探针进行核酸杂交","B. 与特异性抗体反应","C. 直接在260 nm下肉眼观察条带","D. 用DNA聚合酶从膜上延伸合成"],"oe":["A正确：Northern以互补核酸探针与目标RNA杂交。","B错误：抗体与蛋白反应，是Western blotting的特点。","C错误：260 nm只能总体反映核酸吸收，不能特异识别某一RNA序列。","D错误：DNA聚合酶延伸不是Northern的检测方式。"]},"imageExplain":"看RNA从凝胶转印到膜的过程，与Southern对照：流程相同，只是待测分子由DNA换成了RNA。"},{"i":42,"sec":"老师PPT逐页","title":"Western印迹杂交","notes":"Western印迹把蛋白质从电泳凝胶中转移并结合到硝酸纤维素滤膜上，再与针对特定蛋白质的标记抗体反应，从而检测目标蛋白。它与Southern、Northern的“核酸-核酸杂交”不同，本质是“蛋白-抗体”识别。","points":["检测对象为蛋白质","蛋白质从凝胶转移到硝酸纤维素膜","用特异性抗体识别目标蛋白","抗体可带放射性或其他标记","本质是抗原-抗体反应，非核酸杂交"],"fig":"","page":null,"anim":null,"img":"assets/img/bc12/full43.jpg","srcType":"老师PPT","role":"主线","check":{"kind":"mcq","id":"bc12_check_42","q":"Western blotting将蛋白质从电泳凝胶转移到硝酸纤维素膜后，其特异性检测依赖什么？","a":"B","e":"Western blotting先把蛋白电泳分离并转膜，再用特异性抗体识别目标蛋白，属于蛋白质免疫检测而非核酸杂交。","src":"本页自测","o":["A. 核酸探针与DNA杂交","B. 抗体与目标蛋白的抗原决定簇结合","C. 蛋白质与DNA形成共价键","D. 碱水解产生2′,3′-环磷酸"],"oe":["A错误：核酸探针杂交用于Southern/Northern，不用于Western。","B正确：Western用特异性抗体识别目标蛋白的抗原决定簇。","C错误：Western不依赖蛋白与DNA共价连接。","D错误：2′,3′-环磷酸是RNA碱水解产物，与Western无关。"]},"imageExplain":"看蛋白条带转印到膜后与抗体结合的位置，显色或显影条带对应目标蛋白的分子量与丰度。"},{"title":"AI主讲1：核酸水解总览","sec":"第12章 · AI主讲","notes":"核酸水解是磷酸二酯键断裂。按试剂分酸水解、碱水解、酶水解；按酶作用位置分内切酶/外切酶；按断键方式分3′-OH/5′-磷酸或5′-OH/3′-磷酸产物。","points":["水解=磷酸二酯键断裂。","酸/碱/酶三类。","内切/外切。","3′/5′断键方式。"],"img":"assets/img/bc12/full2.jpg","imageExplain":"看核酸水解的三种方式和断键位置。","srcType":"白话辅助","role":"主线","i":43,"check":{"kind":"mcq","id":"bc12_check_43","q":"关于核酸水解，下列叙述正确的是？","a":"B","e":"核酸水解的本质是磷酸二酯键断裂，按试剂分为酸水解、碱水解和酶水解；内切酶切链内部，外切酶从末端切；2′,3′-环磷酸是碱水解RNA的产物。","src":"本页自测","o":["A. 水解只断裂氢键，不涉及共价键","B. 水解的本质是磷酸二酯键断裂，可按酸、碱、酶分类","C. 外切酶从多核苷酸链内部随机切割","D. 酸水解的典型结果是生成2′,3′-环磷酸"],"oe":["A错误：水解断裂的是共价键磷酸二酯键，不是氢键。","B正确：磷酸二酯键断裂，可按酸、碱、酶三类划分。","C错误：从链内部切割的是内切酶，外切酶从末端逐个切。","D错误：2′,3′-环磷酸由碱水解RNA产生，不是酸水解的典型产物。"]}},{"title":"AI主讲2：酸水解与碱水解","sec":"第12章 · AI主讲","notes":"酸水解主要断裂嘌呤糖苷键，生成无嘌呤核酸；碱水解使RNA的2′-OH参与形成2′,3′-环磷酸，RNA易被碱水解，DNA无2′-OH，较抗碱。","points":["酸水解→脱嘌呤。","RNA有2′-OH，易碱解。","DNA无2′-OH，抗碱。","碱解产生2′,3′-环磷酸。"],"img":"assets/img/bc12/full3.jpg","imageExplain":"比较酸水解与碱水解的产物。","srcType":"白话辅助","role":"主线","i":44,"check":{"kind":"mcq","id":"bc12_check_44","q":"RNA容易被碱水解而DNA较抗碱，其关键结构原因是？","a":"B","e":"RNA核糖的2′-OH在碱作用下可进攻磷酸二酯键，形成2′,3′-环磷酸并促使链断裂；DNA的脱氧核糖无2′-OH，因而较抗碱。","src":"本页自测","o":["A. RNA含有尿嘧啶","B. RNA的核糖2′-OH可参与形成2′,3′-环磷酸","C. DNA含有胸腺嘧啶","D. DNA是双链而RNA是单链"],"oe":["A错误：尿嘧啶本身不是RNA易碱解的关键原因。","B正确：2′-OH参与形成2′,3′-环磷酸，是RNA易碱解的结构基础。","C错误：胸腺嘧啶与抗碱性的关系不是关键。","D错误：单双链不是RNA易碱解而DNA抗碱的主要原因。"]}},{"title":"AI主讲3：酶水解与限制酶","sec":"第12章 · AI主讲","notes":"RNase水解RNA，DNase水解DNA；内切酶切链内部，外切酶从末端逐个切。限制性内切酶识别特定回文序列，Ⅱ型酶在识别位点内/附近切割，用于基因工程。","points":["RNase/DNase。","内切/外切。","限制酶识别回文序列。","Ⅱ型酶切割DNA。"],"img":"assets/img/bc12/full10.jpg","imageExplain":"看限制酶识别位点与切割位点。","srcType":"白话辅助","role":"主线","i":45,"check":{"kind":"mcq","id":"bc12_check_45","q":"关于酶水解与限制性内切酶，下列叙述正确的是？","a":"B","e":"Ⅱ型限制酶识别特定回文序列并在识别位点内或附近定点切割，是基因工程常用工具；RNase水解RNA，DNase水解DNA；内切酶切内部，外切酶从末端切。","src":"本页自测","o":["A. 所有限制性内切酶都在回文序列内部切割","B. Ⅱ型限制酶识别特定回文序列，并在识别位点内或附近切割","C. 外切酶识别回文序列并从链末端切割","D. RNase可以特异切割DNA"],"oe":["A错误：并非所有限制酶都在回文序列内部切割，不同类型切割位置不同。","B正确：Ⅱ型限制酶识别回文序列并在识别位点内或附近切割。","C错误：识别回文序列并定点切割的是限制性内切酶，不是外切酶。","D错误：RNase水解RNA，不特异切割DNA；切DNA的是DNase。"]}},{"title":"AI主讲4：碱基与核苷酸的解离","sec":"第12章 · AI主讲","notes":"碱基杂环N和取代基既能结合又能释放质子，是兼性离子；核苷/核苷酸保留碱基解离性质。不同基团pKa不同，净电荷随pH变化。","points":["碱基是兼性离子。","不同基团有不同pKa。","净电荷随pH变化。","pI取两侧pKa平均。"],"img":"assets/img/bc12/full18.jpg","imageExplain":"看碱基/核苷酸的解离基团。","srcType":"白话辅助","role":"主线","i":46,"check":{"kind":"mcq","id":"bc12_check_46","q":"关于碱基、核苷和核苷酸的解离性质，下列叙述正确的是？","a":"B","e":"碱基杂环N和取代基既能结合又能释放质子，故为兼性离子；不同基团pKa不同，净电荷随pH变化，pI可取两侧pKa的平均值。","src":"本页自测","o":["A. 碱基既不能结合质子也不能释放质子","B. 碱基杂环上的氮及取代基可结合或释放质子，具有兼性离子性质","C. 同一分子中所有解离基团的pKa完全相同","D. 分子的净电荷不随pH变化"],"oe":["A错误：碱基可结合或释放质子，并非惰性。","B正确：碱基杂环N及取代基可结合或释放质子，呈兼性离子性质。","C错误：不同解离基团的pKa不同。","D错误：净电荷随pH改变而改变。"]}},{"title":"AI主讲5：核酸的紫外吸收","sec":"第12章 · AI主讲","notes":"嘌呤/嘧啶共轭双键使核酸在260 nm有强吸收；蛋白质在280 nm吸收。A260可用于定量和纯度判断。","points":["核酸A260。","蛋白A280。","共轭双键。","A260/A280判纯度。"],"img":"assets/img/bc12/full25.jpg","imageExplain":"看260 nm吸收与碱基共轭体系。","srcType":"白话辅助","role":"主线","i":47,"check":{"kind":"mcq","id":"bc12_check_47","q":"核酸在260 nm有强吸收、蛋白质在280 nm有吸收，其结构基础分别是？","a":"B","e":"嘌呤、嘧啶碱基的共轭双键体系使核酸在260 nm强吸收；蛋白质中芳香族氨基酸（如色氨酸、酪氨酸）在280 nm有吸收。","src":"本页自测","o":["A. 核酸的磷酸基团；蛋白质的肽键","B. 核酸碱基的共轭双键体系；蛋白质中的芳香族氨基酸","C. 核酸的戊糖；蛋白质的氨基","D. 核酸的氢键；蛋白质的二硫键"],"oe":["A错误：磷酸基团和肽键不是260/280 nm吸收的主要结构基础。","B正确：碱基共轭双键对应A260，芳香族氨基酸对应A280。","C错误：戊糖和氨基不是这两个吸收峰的主要来源。","D错误：氢键和二硫键不决定260/280 nm吸收。"]}},{"title":"AI主讲6：纯度、含量与定量","sec":"第12章 · AI主讲","notes":"双链DNA A260=1≈50 μg/mL，单链DNA≈33 μg/mL，RNA≈40 μg/mL；A260/A280≈1.8（DNA）或2.0（RNA）表示较纯。摩尔磷吸光系数ε(P)可用于计算。","points":["dsDNA 50 μg/mL/A260。","RNA 40，ssDNA 33。","A260/A280判纯度。","ε(P)计算浓度。"],"img":"assets/img/bc12/full27.jpg","imageExplain":"看A260/A280与浓度换算。","srcType":"白话辅助","role":"主线","i":48,"check":{"kind":"mcq","id":"bc12_check_48","q":"用A260法测定核酸浓度时，下列对应关系正确的是？","a":"A","e":"标准换算为：双链DNA A260=1≈50 μg/mL，单链DNA≈33 μg/mL，RNA≈40 μg/mL；A260/A280约1.8（DNA）或2.0（RNA）提示较纯。","src":"本页自测","o":["A. 双链DNA A260=1约相当于50 μg/mL","B. RNA A260=1约相当于33 μg/mL","C. 单链DNA A260=1约相当于50 μg/mL","D. RNA A260=1约相当于50 μg/mL"],"oe":["A正确：双链DNA A260=1约相当于50 μg/mL。","B错误：RNA的系数是40 μg/mL，不是33。","C错误：单链DNA的系数是33 μg/mL，不是50。","D错误：RNA的系数是40 μg/mL，不是50。"]}},{"title":"AI主讲7：变性、Tm与影响因素","sec":"第12章 · AI主讲","notes":"DNA变性是双螺旋解开，但共价键不断；260 nm吸收升高（增色效应）。Tm是变性一半时的温度；GC含量越高、离子强度越高，Tm越高。","points":["变性≠降解。","增色效应A260↑。","Tm=50%变性温度。","GC高/盐高→Tm高。"],"img":"assets/img/bc12/full31.jpg","imageExplain":"看变性曲线与Tm。","srcType":"白话辅助","role":"主线","i":49,"check":{"kind":"mcq","id":"bc12_check_49","q":"关于DNA变性与Tm，下列叙述正确的是？","a":"D","e":"变性是双螺旋解开而共价键不断，伴随增色效应（A260升高）；Tm为50%双链解开时的温度，GC含量越高、离子强度越高，Tm越高。","src":"本页自测","o":["A. 变性时磷酸二酯键断裂，DNA被降解","B. 变性后A260降低","C. Tm是A260达到最大值时的温度","D. Tm是双链解开50%时的温度，GC含量和离子强度越高Tm越高"],"oe":["A错误：变性只解开双螺旋，不打断磷酸二酯键，不等于降解。","B错误：变性后A260升高（增色效应），不是降低。","C错误：Tm对应50%变性，不是A260最大时。","D正确：Tm为50%变性温度，GC高、盐高使Tm升高。"]}},{"title":"AI主讲8：复性、Cot与复杂度","sec":"第12章 · AI主讲","notes":"变性DNA在适当条件下复性，A260下降（减色效应）。Cot1/2反映序列复杂度：重复序列复性快、Cot1/2小；单拷贝序列复性慢、Cot1/2大。","points":["复性A260↓。","Cot1/2=复性一半。","重复序列快。","单拷贝慢。"],"img":"assets/img/bc12/full35.jpg","imageExplain":"看Cot曲线三部分。","srcType":"白话辅助","role":"主线","i":50,"check":{"kind":"mcq","id":"bc12_check_50","q":"Cot1/2值与DNA序列复杂度的关系是？","a":"C","e":"Cot1/2越小表示复性越快。高度重复序列复性快、Cot1/2小；单拷贝序列复杂度高、复性慢、Cot1/2大。","src":"本页自测","o":["A. 重复序列Cot1/2大，复性慢","B. 单拷贝序列Cot1/2小，复性快","C. 重复序列Cot1/2小、复性快；单拷贝序列Cot1/2大、复性慢","D. Cot1/2与序列复杂度无关"],"oe":["A错误：重复序列复性快，Cot1/2小而非大。","B错误：单拷贝序列复性慢，Cot1/2大而非小。","C正确：重复序列Cot1/2小、复性快；单拷贝序列Cot1/2大、复性慢。","D错误：Cot1/2正是反映序列复杂度的重要指标。"]}},{"title":"AI主讲9：核酸杂交与印迹","sec":"第12章 · AI主讲","notes":"杂交基于变性-复性：互补单链形成双链。Southern检测DNA，Northern检测RNA，Western检测蛋白质（抗体，不是核酸杂交）。","points":["杂交=互补链复性。","Southern：DNA。","Northern：RNA。","Western：蛋白。"],"img":"assets/img/bc12/full38.jpg","imageExplain":"看Southern转膜与杂交流程。","srcType":"白话辅助","role":"主线","i":51,"check":{"kind":"mcq","id":"bc12_check_51","q":"下列方法与其检测对象的对应，错误的是？","a":"D","e":"Southern检测DNA，Northern检测RNA，二者均用核酸探针；Western检测蛋白质，用抗体，不属于核酸杂交。","src":"本页自测","o":["A. Southern blotting—DNA","B. Northern blotting—RNA","C. Western blotting—蛋白质","D. Western blotting—DNA"],"oe":["A正确：Southern对应DNA。","B正确：Northern对应RNA。","C正确：Western对应蛋白质。","D错误：Western检测蛋白质而非DNA，且用抗体不用核酸探针。"]}},{"title":"AI主讲10：电泳、离心与研究方法","sec":"第12章 · AI主讲","notes":"琼脂糖凝胶电泳按大小分离核酸；密度梯度离心按密度分离；限制酶图谱、杂交、测序用于结构/定位研究。","points":["电泳按大小。","离心按密度。","限制酶图谱。","杂交定位。"],"img":"assets/img/bc12/full26.jpg","imageExplain":"看电泳/离心在研究中的位置。","srcType":"白话辅助","role":"主线","i":52,"check":{"kind":"mcq","id":"bc12_check_52","q":"关于核酸的研究方法，下列叙述错误的是？","a":"D","e":"琼脂糖凝胶电泳主要按分子大小分离核酸；密度梯度离心按密度分离；限制酶图谱、杂交和测序用于结构或定位研究。","src":"本页自测","o":["A. 琼脂糖凝胶电泳主要按分子大小分离核酸","B. 密度梯度离心可按密度差异分离","C. 限制酶图谱可用于DNA结构分析","D. 凝胶电泳主要按碱基序列分离核酸"],"oe":["A正确：凝胶电泳主要按分子大小分离。","B正确：密度梯度离心按密度差异分离。","C正确：限制酶图谱可用于DNA结构分析。","D错误：常规凝胶电泳不按碱基序列分离，而主要按大小。"]}},{"title":"原书精读1：酸碱水解比较","sec":"第12章 · AI主讲","notes":"RNA核糖2′-OH使碱水解形成2′,3′-环磷酸，RNA易碱解；DNA无2′-OH，抗碱。酸水解主要脱嘌呤。","points":["RNA易碱解","DNA抗碱","酸水解脱嘌呤","2′,3′-环磷酸"],"img":"assets/img/bc12/full3.jpg","imageExplain":"对照RNA/DNA碱水解差异。","table":"第12章 · 原书精读","srcType":"白话辅助","role":"主线","i":53,"check":{"kind":"judge","id":"bc12_check_53","q":"DNA因缺乏2′-OH，对碱水解比RNA更稳定。","a":"对","e":"RNA核糖的2′-OH在碱性条件下可参与形成2′,3′-环磷酸，使RNA易被碱水解；DNA为脱氧核糖、无2′-OH，故较抗碱。","src":"本页自测"}},{"title":"原书精读2：限制酶与命名","sec":"第12章 · AI主讲","notes":"限制酶识别回文序列；Ⅱ型酶切割位点固定；命名含菌属首字母、种名、株系和序号。","points":["回文序列","Ⅱ型酶","切割位点","命名规则"],"img":"assets/img/bc12/full14.jpg","imageExplain":"看识别位点与切割。","table":"第12章 · 原书精读","srcType":"白话辅助","role":"主线","i":54,"check":{"kind":"mcq","id":"bc12_check_54","q":"限制酶名称EcoRI中，“E”“co”“R”“I”分别大致表示？","a":"A","e":"限制酶命名通常含来源菌属首字母、种名、株系和序号，例如EcoRI来自大肠杆菌某株系，Ⅰ为其序号。","src":"本页自测","o":["A. 属名首字母、种名、株系、序号","B. 酶切位点、基因、蛋白、亚基","C. 内切、外切、识别、切割","D. 属、科、目、种"],"oe":["A正确：依次表示属名首字母、种名、株系和序号。","B错误：这些不是限制酶命名的组成含义。","C错误：命名不表示内切、外切、识别、切割。","D错误：命名不是按属、科、目、种排列。"]}},{"title":"原书精读3：UV吸收与定量","sec":"第12章 · AI主讲","notes":"A260来自碱基共轭双键；A260/A280判纯度；dsDNA 50 μg/mL/A260，RNA 40，ssDNA 33。","points":["A260碱基","A280蛋白","A260/A280","浓度换算"],"img":"assets/img/bc12/full25.jpg","imageExplain":"看UV吸收与纯度。","table":"第12章 · 原书精读","srcType":"白话辅助","role":"主线","i":55,"check":{"kind":"short","id":"bc12_check_55","q":"简述用A260/A280判断核酸纯度的依据，并给出纯DNA和纯RNA的参考比值。","a":"核酸在260 nm吸收、蛋白质在280 nm吸收，因此A260/A280可反映核酸与蛋白的相对含量。纯DNA约为1.8，纯RNA约为2.0；比值明显降低通常提示蛋白质污染。","e":"A260测核酸、A280测蛋白；DNA参考1.8、RNA参考2.0，蛋白污染使比值下降。","src":"本页自测"}},{"title":"原书精读4：变性复性与杂交","sec":"第12章 · AI主讲","notes":"变性增色、复性减色；Tm受GC和盐浓度影响；Southern/Northern/Western分别检测DNA/RNA/蛋白。","points":["增色/减色","Tm","Southern/Northern","Western蛋白"],"img":"assets/img/bc12/full38.jpg","imageExplain":"看杂交与印迹。","table":"第12章 · 原书精读","srcType":"白话辅助","role":"主线","i":56,"check":{"kind":"mcq","id":"bc12_check_56","q":"某DNA样品加热后A260升高，缓慢冷却后A260下降。下列解释正确的是？","a":"B","e":"加热使DNA双螺旋解开，碱基暴露使A260升高（增色效应）；缓慢冷却时互补单链复性，A260下降（减色效应）。此过程不涉及磷酸二酯键断裂。","src":"本页自测","o":["A. 加热使DNA降解为核苷酸，冷却后重新聚合","B. 加热使双螺旋解开产生增色效应，冷却后互补链复性产生减色效应","C. 加热使蛋白质变性，冷却后蛋白质复性","D. A260变化与碱基堆积无关"],"oe":["A错误：变性不解断磷酸二酯键，不是降解为核苷酸。","B正确：解链产生增色效应，复性产生减色效应。","C错误：A260主要反映核酸碱基，不是蛋白质变性复性。","D错误：增色/减色效应与碱基堆积状态的改变密切相关。"]}},{"title":"过程版1：水解怎么断","sec":"第12章 · 过程版","notes":"先看磷酸二酯键，再看酸/碱/酶哪种试剂，最后判断断在3′-O—P还是5′-O—P。","points":["磷酸二酯键","酸/碱/酶","3′/5′断键"],"img":"","imageExplain":"","table":[["方式","产物"],["酸水解","脱嘌呤"],["碱水解","2′,3′-环磷酸"],["内切酶","内部切"],["外切酶","末端切"]],"srcType":"白话辅助","role":"主线","i":57,"check":{"kind":"fill","id":"bc12_check_57","q":"核酸水解时断裂的化学键是____；按所用试剂可分为酸水解、碱水解和____。","a":"磷酸二酯键；酶水解","e":"核酸水解的本质是磷酸二酯键断裂，按试剂分为酸、碱、酶三类水解。","src":"本页自测"}},{"title":"过程版2：UV定量四步","sec":"第12章 · 过程版","notes":"读A260→判断核酸类型→用对应系数→乘稀释倍数。","points":["A260","dsDNA 50","RNA 40","乘稀释"],"img":"","imageExplain":"","table":[["核酸","A260=1对应"],["dsDNA","50 μg/mL"],["ssDNA","33 μg/mL"],["RNA","40 μg/mL"]],"srcType":"白话辅助","role":"主线","i":58,"check":{"kind":"short","id":"bc12_check_58","q":"写出用紫外吸收法测定DNA浓度的四个步骤。","a":"①读取样品A260；②判断核酸类型；③选用对应系数（dsDNA 50、ssDNA 33、RNA 40 μg/mL，对应A260=1）；④乘以稀释倍数得到原样品浓度。","e":"核心是A260读数、定类型、选系数、乘稀释倍数；dsDNA用50 μg/mL。","src":"本页自测"}},{"title":"过程版3：Tm读图","sec":"第12章 · 过程版","notes":"先看曲线中点Tm，再看GC%和盐浓度：GC高、盐高→Tm高。","points":["Tm=50%","GC高Tm高","盐高Tm高"],"img":"","imageExplain":"","table":[["因素","Tm"],["GC↑","↑"],["盐↑","↑"],["变性剂","↓"]],"srcType":"白话辅助","role":"主线","i":59,"check":{"kind":"mcq","id":"bc12_check_59","q":"从DNA变性曲线读取Tm时，正确的做法是？","a":"C","e":"Tm是双链解开50%时的温度，在变性曲线上对应A260升至最大变化量一半的温度；GC含量高、盐浓度高使Tm升高，变性剂使Tm降低。","src":"本页自测","o":["A. 取A260刚开始上升时的温度","B. 取A260达到最大值时的温度","C. 取A260升至最大值一半（即50%变性）所对应的温度，并结合GC含量和盐浓度判断","D. 取曲线最低点所对应的温度"],"oe":["A错误：刚开始上升只表示变性启动，不是50%变性。","B错误：最大值对应完全变性，不是Tm。","C正确：Tm取50%变性处，并受GC含量和盐浓度影响。","D错误：曲线最低点不是Tm的定义位置。"]}},{"title":"过程版4：三种印迹","sec":"第12章 · 过程版","notes":"Southern DNA、Northern RNA、Western蛋白；前两者用核酸探针，Western用抗体。","points":["Southern DNA","Northern RNA","Western蛋白"],"img":"","imageExplain":"","table":[["方法","检测"],["Southern","DNA"],["Northern","RNA"],["Western","蛋白"]],"srcType":"白话辅助","role":"主线","i":60,"check":{"kind":"mcq","id":"bc12_check_60","q":"Southern、Northern、Western三种印迹的关键区别是？","a":"B","e":"Southern检测DNA、Northern检测RNA，二者基于核酸杂交；Western检测蛋白质，基于抗体与抗原结合，不属于核酸杂交。","src":"本页自测","o":["A. 三者都使用核酸探针","B. Southern/Northern用核酸探针分别检测DNA/RNA，Western用抗体检测蛋白质","C. Southern检测RNA，Northern检测DNA","D. Western也属于核酸杂交"],"oe":["A错误：Western用抗体，不用核酸探针。","B正确：Southern/Northern为核酸探针杂交，Western为抗体检测蛋白。","C错误：Southern检测DNA，Northern检测RNA，方向说反。","D错误：Western是蛋白免疫检测，不是核酸杂交。"]}},{"title":"变式1：酸/碱/酶水解","sec":"第12章 · AI主讲","notes":"酸水解脱嘌呤；碱水解RNA；酶水解看内切/外切。","points":["酸脱嘌呤","碱解RNA","酶内/外切"],"img":"","imageExplain":"","table":"第12章 · 变式","srcType":"白话辅助","role":"主线","i":61,"check":{"kind":"mcq","id":"bc12_check_61","q":"下列水解方式与主要结果的对应，正确的是？","a":"C","e":"酸水解主要断裂嘌呤糖苷键，生成无嘌呤核酸；碱水解使RNA形成2′,3′-环磷酸；外切酶从末端切割，内切酶从内部切割。","src":"本页自测","o":["A. 酸水解—RNA降解为2′,3′-环磷酸","B. 碱水解—DNA脱嘌呤","C. 酸水解—脱嘌呤生成无嘌呤核酸","D. 外切酶—从链内部切割"],"oe":["A错误：生成2′,3′-环磷酸的是碱水解RNA，不是酸水解。","B错误：脱嘌呤主要见于酸水解，不是碱水解。","C正确：酸水解主要脱嘌呤，生成无嘌呤核酸。","D错误：外切酶从末端切割，从内部切的是内切酶。"]}},{"title":"变式2：A260/A280","sec":"第12章 · AI主讲","notes":"A260/A280≈1.8 DNA、2.0 RNA；蛋白污染使比值下降。","points":["1.8 DNA","2.0 RNA","蛋白污染↓"],"img":"","imageExplain":"","table":"第12章 · 变式","srcType":"白话辅助","role":"主线","i":62,"check":{"kind":"mcq","id":"bc12_check_62","q":"某DNA样品测得A260/A280=1.5，最可能说明？","a":"B","e":"纯DNA的A260/A280约为1.8，纯RNA约为2.0。比值降至1.5通常提示蛋白质污染；RNA污染一般使比值偏向2.0。","src":"本页自测","o":["A. 样品很纯","B. 存在蛋白质污染，比值低于纯DNA的约1.8","C. 存在RNA污染，比值高于2.0","D. 样品已完全降解为核苷酸"],"oe":["A错误：1.5低于纯DNA参考值1.8，不能说明很纯。","B正确：蛋白质在280 nm吸收，污染会使A260/A280下降。","C错误：RNA污染通常使比值接近或偏向2.0，而非降低到1.5。","D错误：该比值不能直接证明完全降解。"]}},{"title":"变式3：Tm计算","sec":"第12章 · AI主讲","notes":"Tm=81.5+16.6lg[Na+]+0.41(%GC)。","points":["Tm公式","GC↑Tm↑","盐↑Tm↑"],"img":"","imageExplain":"","table":"第12章 · 变式","srcType":"白话辅助","role":"主线","i":63,"check":{"kind":"mcq","id":"bc12_check_63","q":"某DNA的GC含量为40%，Na+浓度为0.1 mol/L（lg0.1=-1）。按Tm=81.5+16.6lg[Na+]+0.41(%GC)计算，Tm约为？","a":"B","e":"代入公式：Tm=81.5+16.6×(-1)+0.41×40=81.5-16.6+16.4=81.3℃。","src":"本页自测","o":["A. 71.3℃","B. 81.3℃","C. 91.3℃","D. 65.0℃"],"oe":["A错误：71.3℃是漏加0.41×40项或计算错误的结果。","B正确：81.5-16.6+16.4=81.3℃。","C错误：91.3℃是把盐项符号用反等计算错误。","D错误：65.0℃与公式代入结果不符。"]}},{"title":"变式4：Cot曲线","sec":"第12章 · AI主讲","notes":"Cot1/2小=重复序列；大=单拷贝。","points":["Cot1/2","重复快","单拷贝慢"],"img":"","imageExplain":"","table":"第12章 · 变式","srcType":"白话辅助","role":"主线","i":64,"check":{"kind":"mcq","id":"bc12_check_64","q":"Cot曲线中，Cot1/2最小（复性最快）的部分通常对应？","a":"B","e":"Cot1/2越小表示复性越快。高度重复序列碰撞配对机会多、复性最快，Cot1/2最小；单拷贝序列复性最慢、Cot1/2最大。","src":"本页自测","o":["A. 单拷贝序列","B. 高度重复序列","C. 蛋白质组分","D. 断裂的双链片段"],"oe":["A错误：单拷贝序列复杂度高、复性慢，Cot1/2大。","B正确：高度重复序列复性最快，Cot1/2最小。","C错误：Cot曲线描述DNA复性，不是蛋白质组分。","D错误：断裂片段不是Cot1/2最小部分的对应解释。"]}},{"title":"变式5：Southern/Northern","sec":"第12章 · AI主讲","notes":"Southern DNA，Northern RNA，Western蛋白。","points":["Southern DNA","Northern RNA","Western蛋白"],"img":"","imageExplain":"","table":"第12章 · 变式","srcType":"白话辅助","role":"主线","i":65,"check":{"kind":"mcq","id":"bc12_check_65","q":"要检测某基因在组织中的mRNA表达水平，应首选？","a":"B","e":"Northern blotting用于检测RNA，可反映特定mRNA的大小和表达水平；Southern检测DNA，Western检测蛋白质。","src":"本页自测","o":["A. Southern blotting","B. Northern blotting","C. Western blotting","D. 密度梯度离心"],"oe":["A错误：Southern检测DNA，不直接反映mRNA表达。","B正确：Northern检测RNA，适合分析mRNA表达水平。","C错误：Western检测蛋白质，不是mRNA。","D错误：密度梯度离心按密度分离，不特异地检测mRNA表达。"]}},{"title":"变式6：限制酶","sec":"第12章 · AI主讲","notes":"识别回文序列，Ⅱ型酶定点切割。","points":["回文","Ⅱ型","定点切"],"img":"","imageExplain":"","table":"第12章 · 变式","srcType":"白话辅助","role":"主线","i":66,"check":{"kind":"mcq","id":"bc12_check_66","q":"Ⅱ型限制性内切酶的主要特点是？","a":"A","e":"Ⅱ型限制酶识别特定的回文序列，并在识别位点内或附近定点切割，切割位点固定，是基因工程的重要工具。","src":"本页自测","o":["A. 识别回文序列，并在识别位点内或附近定点切割","B. 从DNA末端逐个切除核苷酸","C. 只切割单链RNA","D. 随机切割任意DNA序列"],"oe":["A正确：识别回文序列并在识别位点内或附近定点切割。","B错误：从末端逐个切除的是外切酶。","C错误：Ⅱ型限制酶切割DNA，不是只切单链RNA。","D错误：限制酶识别特定序列，不是随机切割。"]}},{"title":"图卡：核酸水解","sec":"第12章 · AI主讲","notes":"磷酸二酯键断裂；酸/碱/酶。","points":["磷酸二酯键","酸/碱/酶"],"img":"assets/img/bc12/full2.jpg","imageExplain":"看水解断键。","table":"第12章 · 图卡","srcType":"白话辅助","role":"主线","i":67,"check":{"kind":"judge","id":"bc12_check_67","q":"核酸水解的化学本质是磷酸二酯键断裂。","a":"对","e":"酸水解、碱水解和酶水解均以磷酸二酯键断裂为核心，只是断键位置和产物不同，例如碱水解RNA可生成2′,3′-环磷酸。","src":"本页自测"}},{"title":"图卡：增色效应","sec":"第12章 · AI主讲","notes":"变性后A260升高；复性后降低。","points":["变性A260↑","复性A260↓"],"img":"assets/img/bc12/full31.jpg","imageExplain":"看变性曲线。","table":"第12章 · 图卡","srcType":"白话辅助","role":"主线","i":68,"check":{"kind":"fill","id":"bc12_check_68","q":"DNA变性时A260____，复性时A260____。","a":"升高；降低","e":"变性使碱基暴露产生增色效应，A260升高；复性使碱基重新堆积产生减色效应，A260降低。","src":"本页自测"}},{"title":"图卡：Tm","sec":"第12章 · AI主讲","notes":"Tm=50%变性温度；GC/盐影响。","points":["Tm","GC","盐"],"img":"assets/img/bc12/full32.jpg","imageExplain":"看Tm曲线。","table":"第12章 · 图卡","srcType":"白话辅助","role":"主线","i":69,"check":{"kind":"mcq","id":"bc12_check_69","q":"当温度达到DNA的Tm时，发生的变化是？","a":"B","e":"Tm是双螺旋解开一半（50%变性）时的温度，此时A260约达到最大变化量的一半，并非全部解链。","src":"本页自测","o":["A. 全部双链都已解开","B. 约50%的双链结构被解开","C. 所有磷酸二酯键断裂","D. A260降到最低"],"oe":["A错误：Tm对应50%变性，不是全部解链。","B正确：Tm定义为约50%双链被解开的温度。","C错误：变性不断裂磷酸二酯键。","D错误：变性过程中A260升高，Tm处不是最低。"]}},{"title":"图卡：Southern","sec":"第12章 · AI主讲","notes":"DNA电泳→变性→转膜→探针杂交。","points":["DNA","转膜","探针"],"img":"assets/img/bc12/full39.jpg","imageExplain":"看Southern流程。","table":"第12章 · 图卡","srcType":"白话辅助","role":"主线","i":70,"check":{"kind":"fill","id":"bc12_check_70","q":"Southern印迹的基本流程中，DNA电泳分离后、转膜之前通常需要先进行____处理。","a":"变性","e":"电泳后需将双链DNA碱变性为单链，才能有效地转移到膜上并与互补探针杂交。","src":"本页自测"}},{"title":"图卡：Northern","sec":"第12章 · AI主讲","notes":"RNA转膜→探针检测表达。","points":["RNA","转膜","表达"],"img":"assets/img/bc12/full41.jpg","imageExplain":"看Northern流程。","table":"第12章 · 图卡","srcType":"白话辅助","role":"主线","i":71,"check":{"kind":"mcq","id":"bc12_check_71","q":"Northern blotting的主要用途是？","a":"B","e":"Northern blotting将RNA转膜后用核酸探针杂交，用于检测特定RNA的大小和表达水平。","src":"本页自测","o":["A. 检测DNA片段的大小","B. 检测RNA分子的大小及表达水平","C. 检测蛋白质的表达","D. 测定DNA的Tm"],"oe":["A错误：检测DNA的是Southern blotting。","B正确：Northern检测RNA大小和表达水平。","C错误：检测蛋白质的是Western blotting。","D错误：Tm通常由变性曲线测定，不是Northern的主要用途。"]}},{"title":"图卡：Western","sec":"第12章 · AI主讲","notes":"蛋白电泳→转膜→抗体检测。","points":["蛋白","抗体","转膜"],"img":"assets/img/bc12/full42.jpg","imageExplain":"看Western流程。","table":"第12章 · 图卡","srcType":"白话辅助","role":"主线","i":72,"check":{"kind":"mcq","id":"bc12_check_72","q":"Western blotting中，转膜后用于检测目标蛋白的是？","a":"B","e":"Western blotting先进行蛋白质电泳和转膜，再用特异性抗体识别目标蛋白，属于免疫检测。","src":"本页自测","o":["A. 互补DNA探针","B. 特异性抗体","C. 溴化乙锭","D. 限制性内切酶"],"oe":["A错误：互补DNA探针用于核酸杂交，不用于Western。","B正确：Western用特异性抗体检测目标蛋白。","C错误：溴化乙锭用于核酸染色，不用于蛋白特异检测。","D错误：限制性内切酶用于切割DNA，不是Western的检测试剂。"]}},{"title":"学习支持1：水解与酶","sec":"第12章 · 学习支持","notes":"酸/碱/酶水解及内切/外切。","points":["酸/碱/酶","内/外切"],"img":"","imageExplain":"","table":[["方式","要点"],["酸","脱嘌呤"],["碱","RNA"],["内切","内部"],["外切","末端"]],"srcType":"白话辅助","role":"主线","i":73,"check":{"kind":"mcq","id":"bc12_check_73","q":"关于核酸水解与酶的作用，下列对应错误的是？","a":"D","e":"酸水解主要脱嘌呤；RNA因2′-OH易被碱水解；内切酶从链内部切割，外切酶从链末端逐个切割。","src":"本页自测","o":["A. 酸水解—脱嘌呤","B. 碱水解—RNA易被水解","C. 内切酶—从链内部切割","D. 外切酶—从链内部随机切割"],"oe":["A正确：酸水解的典型结果是脱嘌呤。","B正确：RNA含2′-OH，易被碱水解。","C正确：内切酶从多核苷酸链内部切割。","D错误：外切酶从末端切割，不是从内部随机切割。"]}},{"title":"学习支持2：UV与纯度","sec":"第12章 · 学习支持","notes":"A260定量，A280蛋白，A260/A280判纯。","points":["A260","A280","比值"],"img":"","imageExplain":"","table":[["指标","意义"],["A260","核酸"],["A280","蛋白"],["A260/A280","纯度"]],"srcType":"白话辅助","role":"主线","i":74,"check":{"kind":"fill","id":"bc12_check_74","q":"紫外检测中，A260主要反映____的含量，A280主要反映____的含量，A260/A280用于判断核酸的____。","a":"核酸；蛋白质；纯度","e":"核酸碱基在260 nm吸收、蛋白质芳香族氨基酸在280 nm吸收，因此A260/A280可判断核酸纯度。","src":"本页自测"}},{"title":"学习支持3：变性复性","sec":"第12章 · 学习支持","notes":"增色/减色、Tm、Cot。","points":["增色","减色","Tm","Cot"],"img":"","imageExplain":"","table":[["现象","变化"],["变性","A260↑"],["复性","A260↓"],["Tm","50%变性"]],"srcType":"白话辅助","role":"主线","i":75,"check":{"kind":"mcq","id":"bc12_check_75","q":"关于DNA变性与复性时的吸光度变化，正确的是？","a":"A","e":"变性使双螺旋解开、碱基暴露，产生增色效应，A260升高；复性使互补链重新形成双螺旋，产生减色效应，A260降低。","src":"本页自测","o":["A. 变性A260升高，复性A260降低","B. 变性A260降低，复性A260升高","C. 变性、复性A260均升高","D. 变性、复性A260均不变"],"oe":["A正确：变性增色（A260升高），复性减色（A260降低）。","B错误：方向说反了。","C错误：复性时A260是降低而不是升高。","D错误：变性和复性均会改变碱基堆积状态，A260随之变化。"]}},{"title":"学习支持4：三种印迹","sec":"第12章 · 学习支持","notes":"Southern/Northern/Western。","points":["Southern","Northern","Western"],"img":"","imageExplain":"","table":[["方法","检测"],["Southern","DNA"],["Northern","RNA"],["Western","蛋白"]],"srcType":"白话辅助","role":"主线","i":76,"check":{"kind":"mcq","id":"bc12_check_76","q":"下列检测对象与方法配对正确的是？","a":"C","e":"Southern检测DNA，Northern检测RNA，Western检测蛋白质，因此只有Western—蛋白质配对正确。","src":"本页自测","o":["A. Southern—RNA","B. Northern—蛋白质","C. Western—蛋白质","D. Western—DNA"],"oe":["A错误：Southern检测DNA，不是RNA。","B错误：Northern检测RNA，不是蛋白质。","C正确：Western检测蛋白质。","D错误：Western检测蛋白质，不是DNA。"]}},{"title":"计算1：A260与DNA浓度","sec":"第12章 · 计算","notes":"dsDNA：A260=1≈50 μg/mL；浓度=A260×50×稀释倍数。RNA用40，ssDNA用33。","points":["dsDNA 50","RNA 40","乘稀释"],"img":"","imageExplain":"","table":[["核酸","系数"],["dsDNA","50 μg/mL"],["ssDNA","33 μg/mL"],["RNA","40 μg/mL"]],"srcType":"白话辅助","role":"主线","i":77,"check":{"kind":"mcq","id":"bc12_check_77","q":"某双链DNA样品稀释100倍后测得A260=0.25。按dsDNA A260=1约相当于50 μg/mL计算，原样品DNA浓度约为？","a":"B","e":"稀释液浓度=0.25×50=12.5 μg/mL；原样品需乘稀释倍数100，即12.5×100=1250 μg/mL（约1.25 mg/mL）。","src":"本页自测","o":["A. 125 μg/mL","B. 1250 μg/mL","C. 12.5 μg/mL","D. 2500 μg/mL"],"oe":["A错误：125 μg/mL相当于少乘或多除10倍。","B正确：0.25×50×100=1250 μg/mL。","C错误：12.5 μg/mL只是稀释后浓度，未乘稀释倍数。","D错误：2500 μg/mL是计算多乘2倍的结果。"]}},{"title":"计算2：Tm与密度","sec":"第12章 · 计算","notes":"Tm=81.5+16.6lg[Na+]+0.41(%GC)；密度ρ=1.660+0.00098(%GC)。","points":["Tm公式","密度公式","GC↑"],"img":"","imageExplain":"","table":[["量","公式"],["Tm","81.5+16.6lg[Na]+0.41GC"],["密度","1.660+0.00098GC"]],"srcType":"白话辅助","role":"主线","i":78,"check":{"kind":"mcq","id":"bc12_check_78","q":"某DNA的GC含量为50%。按ρ=1.660+0.00098(%GC)计算，其密度约为？","a":"B","e":"代入公式：ρ=1.660+0.00098×50=1.660+0.049=1.709 g/cm³。","src":"本页自测","o":["A. 1.660 g/cm³","B. 1.709 g/cm³","C. 1.758 g/cm³","D. 1.611 g/cm³"],"oe":["A错误：1.660是GC为0时的截距，未加GC项。","B正确：1.660+0.00098×50=1.709 g/cm³。","C错误：1.758相当于GC约100%时的结果。","D错误：1.611小于截距，计算方向错误。"]}},{"title":"bc12 使用评估与学习建议","sec":"第12章 · 使用评估","notes":"先AI主讲1-10；再看原书图；最后做题。抓住水解、UV、变性复性、杂交四条主线。","points":["水解","UV","变性复性","杂交"],"img":"","imageExplain":"","table":[["项目","数量"],["总页数","80"],["章测","20选择+5判断+5填空+12简答+6计算+8名词"],["网页题","50"]],"srcType":"白话辅助","role":"主线","i":79,"check":{"kind":"mcq","id":"bc12_check_79","q":"根据bc12的使用评估，本章学习的四条主线不包括？","a":"D","e":"本章学习建议抓住水解、紫外吸收、变性复性、杂交四条主线；氧化磷酸化属于能量代谢内容，不属于本章主线。","src":"本页自测","o":["A. 核酸水解","B. 紫外吸收","C. 变性复性","D. 氧化磷酸化"],"oe":["A不符合题意：核酸水解是本章四条主线之一。","B不符合题意：紫外吸收是本章四条主线之一。","C不符合题意：变性复性是本章四条主线之一。","D正确：氧化磷酸化不属于本章核酸化学主线。"]}}],"mcq":[{"id":"bc12_mcq_2","modI":0,"q":"在 DNA 分子中，腺嘎叭是 20%，则鸟嗓叭是多少? 〈 ) [上海交通大学 2017 研]","o":["A. 20%","B. 30%","C. 40%","D. 50%","E. 35%"],"a":"B","e":"","kp":""},{"id":"bc12_mcq_3","modI":0,"q":"将 RNA 转移到硝酸纤维素膜上，进行分子杂交的技术叫〈 )。[清华大学 2001 研]","o":["A. Southern 杂交法","B. Northern 杂交法","C. ","D. Western 杂交法"],"a":"B","e":"","kp":""},{"id":"bc12_mcq_4","modI":0,"q":"DNA 受热变性时，出现的现象是〈 )。[全国西医综合 2005 研]","o":["A. SRT IR G","B. 在 260nm 波长处的吸光度增高","C. 碱基对以共价键连接","D. 溶液黏度增加"],"a":"B","e":"","kp":""},{"id":"bc12_mcq_5","modI":0,"q":"(Sik) 一溶液含有 PCR 扩增后的 DNA 产物，在 95C加热 10min，然后冰上快速冷却，以下变化将发生 ( )。[中科院水生生物研究所 2007 WF]","o":["A. 该溶液在 260nm 的吸光度将增加","D. ","E. 以上的变化都不会有"],"a":"A","e":"","kp":""}],"judge":[],"fill":[],"short":[{"id":"bc12_short_1","modI":0,"q":"为什么 DNA 比 RNA 不易被碱水解?","a":"RNA 的磷酸酯键易被碱水解产生核昔酸, 是因为 RNA 的核糖上有 2’-OH 基, 在碱作用下形成磷酸三酯。 磅酸三酯极不稳定，随即分解,产生核苷 2,3'-环磷酸酯。该环磷酸酯继续水解产生 2-核苷酸和 3-核昔酸。DNA 的脱氧核糖无 2-OH 基，不能形成碱水解的中间产物，故对碱有一定抗性。","kps":"","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第12章笔记"},{"id":"bc12_short_2","modI":0,"q":"试述核酸酶的种类和分类依据。","a":"核酸酶的种类和分类依据如下: (1) 按底物专一性分类 已作用于核糖核酸的称为核糖核酸酶; 名作用于脱氧核糖核酸的称为脱氧核糖核酸酶。 (2) 按对底物作用的方式分类 名核酸内切酶，内切酶的作用点在多核苷酸链的内部; @@核酸外切酶，外切酶的作用点从多核昔酸链的末端开始，逐个地将核苷酸切下，从而对核酸进行降解。 (3) 按磷酸二酯键断裂的方式分类 在 3-OH 与磷酸基之间断裂，其产物是 5'- BERR AT RR EAR: @在 5-OH 与磷酸基之间断裂，其产物为 3磷酸核苷酸或寡核苷酸。 (4) 其他分类标准 包对底物二级结构的专一性: a. SUE, (FFP UE AR: b.，单链酶，作用于单链。 名核酸外切酶作用的方向性: a. 3人一5'核酸外切酶， b. 5人一3'核酸外切酶。 @@对磷酸二酯键两侧的碱基有无选择性等。","kps":"","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第12章笔记"},{"id":"bc12_short_3","modI":0,"q":"为什么说碱基、核苷和核昔酸是兼性离子? 是否它们都是兼性离子?","a":"〈1) 由于喀啶和味叭化合物杂环中的氮以及各取代基具有结合和释放质子的能力，所以这些物质既有碱 性解离又有酸性解离的性质，所以说，碱基是兼性离子。 (2) 核昔和核昔酸的碱基与游离碱基的解离性质相近，所以它们也是兼性离子。","kps":"","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第12章笔记"},{"id":"bc12_short_4","modI":0,"q":"5'-鸟苷酸的 PK’) 为 0.7，pK' WN 2.4, pK 为 6.1，pK'4 为 9.4，这些 pK各代表什么基团的解离常数? 其 等电点 〈pI) 是多少?","a":"pPK' 为第一个磷酸基的解离常数，pK' 为含氮环上=NH-_ -上的解离常数，pK': 为第二个磷酸基的解离 常数，pK'4 为含氛环上一NH 的解离常数。其等电点为 pI王 (PK'十pK'2 ) /2= (0.7+2.4) /2=1.6","kps":"","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第12章笔记"},{"id":"bc12_short_5","modI":0,"q":"为什么 DNA 酸碱滴定的正向曲线和反向曲线有显著的不同?","a":"DNA 酸碱进行反向滴定时的曲线和正向滴定曲线显著不同。是因为开始滴定时，没有酸碱基团解离， 非缓冲区较宽, 在 pH4.5一11.0 之间; 而在反向滴定中非缓冲区只存在于 pH6一9 之间。这就是说, 当最初的 DNA 溶液超过 pH4.5 和 pH11.0 时即迅速释放出酸碱基团参与 pH2.0一6.0 和 pH9.0一12.0 范围的滴定。","kps":"","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第12章笔记"},{"id":"bc12_short_6","modI":0,"q":"有一纯的质粒 DNA 溶液，共 0.5mL，取少量稀释 100 倍后测得 Azeo 为 0.330，计算此溶液共有 DNA 多 少微克? CERI DNAs (P) 为 6600，lmol 磷 DNA 平均为 310g)","a":"已知 Aaeo为 0.330，s (P) 为 6600，则稀释后的磷 DNA 溶液的浓度为 c一Aneo/ (e (P) XL) =0.33/6600=5 X 10 “mol/L 稀释液中磷 DNA [SERB VX BORE AEX c=0.5 X10 *X 100X0.5X 10 °=2.5X 10 “mol 己知 Imol # DNA 平均为 310g，所以浴液共有 DNA 的量为 310g mol 'X2.5X 10 ° mol=775pg","kps":"","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第12章笔记"},{"id":"bc12_short_7","modI":0,"q":"何谓增色效应? 何谓减色效应?","a":"(1) 增色效应是指与天然 DNA 相比，变性 DNA 双螺旋破坏，碱基充分外露，使得紫外吸收增加的现 象。 (2) 减色效应是指复性后紫外吸收值降低的现象。","kps":"","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第12章笔记"},{"id":"bc12_short_8","modI":0,"q":"肺炎球菌 DNA 的 G+C 含量为 40%，在 0.1ImoyL 盐溶液中其 Tw值是多少?","a":"通常把加热变性使 DNA 的双螺旋结构失去一半时的温度称为该 DNA 的熔点或溶解温度，用 Tw表示。 测定 Ta值，可以推算出 DNA 的碱基的百分组成。 其经验公式为 Ty=81.5°C+16.6 (lg[Na]) +0.41XX¢icr BRI G+C 的含量为 40%，得出 Ta一81.3'C。","kps":"","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第12章笔记"},{"id":"bc12_short_9","modI":0,"q":"某真核生物基因组 DNA 变性后在标准条件下〈溶液阳离子浓度 0. 18mol/L, DNA 片段大小 400bp) 复 性，测得复性曲线分为三部分，快速复性部分占总量 25%，Cotm为 0.0013; 中间部分占 30%，Cot 为 1.9; 组 慢复性部分占 45%，Cotvz 为 630，试计算此基因组高度重复、中等重复和单拷贝序列的复杂度和拷贝数。(已知 大肠杆菌 DNA KA 4.64X 10%bp, Coty 9 9)","a":"在一定条件下，复性反应的速度可以用 Coty, 来衡量。Co 为变性 DNA 复性时的初始浓度，以核苷酸的 摩尔浓度表示，t 为时间，以秒表示，Cotp 表示复性一半的 Cot 值。它对特定 DNA 分子来说是常数，其速率主 由 DNA 中重复序列的含量决定。重复序列复杂程度低，复性速率最快，其次是中等重复序列，单一序列复杂程 度高，复性速率最慢。 (1) 以大肠杆菌 DNA 的相对分子质量为基准，相对分子质量平均大小为 4.64X10\"bp/9一5.2X107bp。 C2) 其中快速复性部分为高度重复序列占总量 25%, Coty 2 为 00013，校正 Coty ,>为 23% X0.0013王3.25勾 10 +，复杂度为 3.25X10“X5.2X10:一169bp，找贝数为 630/0.0013一4.8X10;。 (3) 其中中间速度复性部分为中度重复序列占总量 30%，Cot ,> 为 1.9，校正 Cot ,>为 30%X1.9=0.37，复 杂度为 0.57X5.2X10王3.0X107bp，拷贝数为 630/1.9一331。 (4) 其中缓慢复性部分为单一序列占总量 45%, Coty ,>为 630，校正 Coty ,>为 45% X 630王283.5，复杂度为","kps":"","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第12章笔记"},{"id":"bc12_short_10","modI":0,"q":"5X5.2X105一1.47X108bp，找贝数为 1 。 LL. 核酸杂交的分子基础是什么?x 有哪些应用价值?","a":"C1) 核酸分子杂交是指不同来源的具有互补序列的两条核酸单链在一定条件下按照碱基互补配对的原则 形成双链的过程.可以是 DNA-DNA, DNA-RNA, RNA-RNA.。 其分子基础就是基于核酸分子的变性和复性原理。 (2) 应用: 包检测待定生物有机体之间是否存在亲缘关系; @@用来揭示核酸片段中某一特定基因的存在与否、拷贝数及表达丰度。","kps":"","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第12章笔记"},{"id":"bc12_short_11","modI":0,"q":"什么是 Southern 印迹法? 什么是 Northern 印迹法?","a":"(1) Southern 印迹法: 由 E.M.Southern 于 1975 年建立，将变性 DNA 从电泳凝胶通过毛细管作用转移 到纤维素膜等固相介质上，然后进行 DNA 杂交的操作过程。 (2) Northern 印迹法: MPR RNA 印迹技术，按以上方法的同样原理建立起来的 RNA 转移的方法，将变形 凝胶电泳分开的 RNA 转移到硝酸纤维素膜上，与放射性同位素标记的单链 DNA 或 RNA 探针杂交，检测特异 RNA.","kps":"","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第12章笔记"},{"id":"bc12_short_12","modI":0,"q":"G+C 2 EN 40%1K) DNA 其密度为多少?","a":"按照计算公式 p=1.660+0.00098 (%G+C) g/cm 得 p=1.660+0.00098 X 一1.699g/cm 故其密度为 1.699g/cm。 14， 比较蔗糖密度梯度超离心与氯化钨密度梯度超离心的异同。 答: CL) 相同之处: 都属于密度梯度离心，是用一定的介质在离心管内形成一不连续的密度梯度，将待测物 混悬液或匀浆置于介质的项部，通过重力或离心力场的作用使待测样品分层分离。 (2) 不同之处;蔗糖密度梯度超离心依据的原理是沉降速率离心，使用的介质为蔗糖，莽糖水溶性大，人性 质稳定，渗透压高，价格低康容易制备，是实验室常用的用于细胞器、病毒、RNA 分离的梯度材料，但由于有 较大的渗透压,不宜用于细胞的分离;氯化钨密度梯度超离心依据的原理是沉降平衡离心, 使用的介质为氯化钨， 氯化钨是一种离子型介质、水溶性大，由于它是重金属盐类，在离心时形成的梯度有较好的分辩率，被广泛用于 DNA、质粒、病毒和脂蛋白的分离，但分离慢，价格贵。","kps":"","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第12章笔记"}],"calc":[],"term":[]}],"mcq":[{"id":"bc12_mcq_2","modI":0,"q":"在 DNA 分子中，腺嘎叭是 20%，则鸟嗓叭是多少? 〈 ) [上海交通大学 2017 研]","o":["A. 20%","B. 30%","C. 40%","D. 50%","E. 35%"],"a":"B","e":"A=T=20%，G+C=60%，G=C=30%。","kp":"","oe":["A错误：A=20%，T=20%。","B正确：A=T=20%，G+C=60%，G=C=30%。","C错误：G不是40%。","D错误：G不是50%。","E错误：G不是35%。"]},{"id":"bc12_mcq_3","modI":0,"q":"将 RNA 转移到硝酸纤维素膜上，进行分子杂交的技术叫〈 )。[清华大学 2001 研]","o":["A. Southern 杂交法","B. Northern 杂交法","C. ","D. Western 杂交法"],"a":"B","e":"Northern检测RNA。","kp":"","oe":["A错误：Southern检测DNA。","B正确：Northern检测RNA。","C错误：不是核酸杂交。","D错误：Western检测蛋白。"]},{"id":"bc12_mcq_4","modI":0,"q":"DNA 受热变性时，出现的现象是〈 )。[全国西医综合 2005 研]","o":["A. SRT IR G","B. 在 260nm 波长处的吸光度增高","C. 碱基对以共价键连接","D. 溶液黏度增加"],"a":"B","e":"变性后碱基暴露，A260升高。","kp":"","oe":["A错误：变性不破坏共价键。","B正确：变性碱基暴露，A260升高。","C错误：碱基对靠氢键，不共价。","D错误：变性黏度下降。"]},{"id":"bc12_mcq_5","modI":0,"q":"(Sik) 一溶液含有 PCR 扩增后的 DNA 产物，在 95C加热 10min，然后冰上快速冷却，以下变化将发生 ( )。[中科院水生生物研究所 2007 WF]","o":["A. 该溶液在 260nm 的吸光度将增加","D. ","E. 以上的变化都不会有"],"a":"A","e":"加热变性→增色效应。","kp":"","oe":["A正确：加热变性后A260升高。","B错误：不是降低。","C错误：不是不变。","D错误：260吸收会变化。","E错误：有明显变化。"]},{"id":"bc12_mcq6","modI":0,"q":"RNA比DNA更容易被碱水解，主要原因是？","o":["A. RNA有2′-OH","B. RNA有2′-H","C. RNA是单链","D. RNA含U"],"a":"A","e":"RNA核糖2′-OH参与形成2′,3′-环磷酸中间物，使磷酸二酯键易水解；DNA无2′-OH，较抗碱。","kp":"","kpId":"bc12_s0_43","oe":["正确：2′-OH参与碱解中间物。","错误：DNA才是2′-H。","错误：单链不是主因。","错误：U不决定碱解。"]},{"id":"bc12_mcq7","modI":0,"q":"酸水解核酸主要产生？","o":["A. 无嘌呤核酸","B. 无嘧啶核酸","C. 单核苷酸","D. 核苷"],"a":"A","e":"酸水解主要断裂嘌呤糖苷键，生成无嘌呤核酸。","kp":"","kpId":"bc12_s0_43","oe":["正确：酸水解主要脱嘌呤。","错误：不是无嘧啶核酸。","错误：产物不是单核苷酸为主。","错误：不是核苷。"]},{"id":"bc12_mcq8","modI":0,"q":"限制性内切酶通常识别？","o":["A. 回文序列","B. polyA","C. 启动子","D. 终止子"],"a":"A","e":"Ⅱ型限制酶识别特定回文序列并在固定位置切割。","kp":"","kpId":"bc12_s0_43","oe":["正确：识别回文序列。","错误：polyA不是识别序列。","错误：启动子是转录调控。","错误：终止子不是限制酶位点。"]},{"id":"bc12_mcq9","modI":0,"q":"核酸260nm紫外吸收主要来自？","o":["A. 碱基共轭双键","B. 磷酸二酯键","C. 糖苷键","D. 肽键"],"a":"A","e":"嘌呤/嘧啶的共轭双键产生260nm吸收。","kp":"","kpId":"bc12_s0_43","oe":["正确：碱基共轭双键。","错误：磷酸二酯键不产生260吸收。","错误：糖苷键不是主要吸收。","错误：肽键在蛋白。"]},{"id":"bc12_mcq10","modI":0,"q":"双链DNA A260=1约相当于多少浓度？","o":["A. 50 μg/mL","B. 1 μg/mL","C. 500 μg/mL","D. 5 mg/mL"],"a":"A","e":"dsDNA A260=1≈50 μg/mL。","kp":"","kpId":"bc12_s0_43","oe":["正确：50 μg/mL。","错误：太小。","错误：太大。","错误：单位不对。"]},{"id":"bc12_mcq11","modI":0,"q":"DNA的A260/A280约为？","o":["A. 1.8","B. 0.5","C. 3.0","D. 0"],"a":"A","e":"纯DNA约1.8；RNA约2.0；蛋白污染使比值下降。","kp":"","kpId":"bc12_s0_43","oe":["正确：约1.8。","错误：0.5表示严重蛋白污染。","错误：3.0不是纯DNA。","错误：0不可能。"]},{"id":"bc12_mcq12","modI":0,"q":"DNA热变性时？","o":["A. A260升高","B. A260降低","C. 共价键断裂","D. 黏度升高"],"a":"A","e":"双螺旋解开，碱基暴露，A260升高（增色效应）。","kp":"","kpId":"bc12_s0_43","oe":["正确：A260升高。","错误：不是降低。","错误：共价键不断。","错误：黏度下降。"]},{"id":"bc12_mcq13","modI":0,"q":"Tm是指？","o":["A. 50%变性时的温度","B. 完全变性温度","C. 复性温度","D. 退火温度"],"a":"A","e":"Tm为双螺旋失去一半时的温度。","kp":"","kpId":"bc12_s0_43","oe":["正确：50%变性温度。","错误：不是完全变性。","错误：不是复性温度。","错误：退火是杂交条件。"]},{"id":"bc12_mcq14","modI":0,"q":"GC含量升高时Tm通常？","o":["A. 升高","B. 降低","C. 不变","D. 变为0"],"a":"A","e":"G-C有3个氢键，GC高更稳定，Tm升高。","kp":"","kpId":"bc12_s0_43","oe":["正确：GC高Tm高。","错误：AT高Tm低。","错误：会变。","错误：不会为0。"]},{"id":"bc12_mcq15","modI":0,"q":"复性时紫外吸收？","o":["A. 降低","B. 升高","C. 不变","D. 消失"],"a":"A","e":"复性碱基重新堆积，A260降低（减色效应）。","kp":"","kpId":"bc12_s0_43","oe":["正确：复性A260降低。","错误：升高是变性。","错误：会变。","错误：不会消失。"]},{"id":"bc12_mcq16","modI":0,"q":"Cot1/2较小说明？","o":["A. 重复序列多","B. 单拷贝多","C. 复杂度高","D. 变性难"],"a":"A","e":"重复序列复性快，Cot1/2小。","kp":"","kpId":"bc12_s0_43","oe":["正确：重复序列多。","错误：单拷贝Cot1/2大。","错误：复杂度高复性慢。","错误：不是变性难。"]},{"id":"bc12_mcq17","modI":0,"q":"Southern印迹检测？","o":["A. DNA","B. RNA","C. 蛋白","D. 脂质"],"a":"A","e":"Southern检测DNA，Northern检测RNA，Western检测蛋白。","kp":"","kpId":"bc12_s0_43","oe":["正确：DNA。","错误：RNA是Northern。","错误：蛋白是Western。","错误：脂质不是。"]},{"id":"bc12_mcq18","modI":0,"q":"Northern印迹检测？","o":["A. RNA","B. DNA","C. 蛋白","D. 糖"],"a":"A","e":"Northern检测RNA。","kp":"","kpId":"bc12_s0_43","oe":["正确：RNA。","错误：DNA是Southern。","错误：蛋白是Western。","错误：糖不是。"]},{"id":"bc12_mcq19","modI":0,"q":"Western印迹检测？","o":["A. 蛋白","B. DNA","C. RNA","D. 脂质"],"a":"A","e":"Western用抗体检测蛋白。","kp":"","kpId":"bc12_s0_43","oe":["正确：蛋白。","错误：DNA是Southern。","错误：RNA是Northern。","错误：脂质不是。"]},{"id":"bc12_mcq20","modI":0,"q":"DNA密度随GC含量升高？","o":["A. 升高","B. 降低","C. 不变","D. 先升后降"],"a":"A","e":"ρ=1.660+0.00098(%GC)，GC↑密度↑。","kp":"","kpId":"bc12_s0_43","oe":["正确：GC高密度高。","错误：不是降低。","错误：会变。","错误：不是先升后降。"]},{"id":"bc12_mcq21","modI":0,"q":"DNA和RNA共有的碱基是？","o":["A. A、G、C","B. A、G、T","C. A、G、U","D. T、U、C"],"a":"A","e":"DNA为A/G/C/T，RNA为A/G/C/U，共有A、G、C。","oe":["正确：A、G、C共有。","错误：T只在DNA。","错误：U只在RNA。","错误：T/U不共有。"],"kp":"","kpId":"bc12_s0_43"}],"judge":[{"id":"bc12_judge1","modI":0,"q":"DNA比RNA更耐碱水解。","a":"对","e":"DNA无2′-OH，不能形成2′,3′-环磷酸中间物，较抗碱。"},{"id":"bc12_judge2","modI":0,"q":"DNA变性后260nm吸收降低。","a":"错","e":"变性后碱基暴露，A260升高（增色效应）。"},{"id":"bc12_judge3","modI":0,"q":"GC含量越高，Tm越高。","a":"对","e":"G-C有3个氢键，GC高更稳定。"},{"id":"bc12_judge4","modI":0,"q":"Southern印迹检测RNA。","a":"错","e":"Southern检测DNA；Northern检测RNA。"},{"id":"bc12_judge5","modI":0,"q":"限制性内切酶可识别特定回文序列。","a":"对","e":"Ⅱ型限制酶识别回文序列并定点切割。"}],"fill":[{"id":"bc12_fill1","modI":0,"q":"RNA易被碱水解是因为核糖有______。","a":"2′-OH","e":"2′-OH参与形成2′,3′-环磷酸。"},{"id":"bc12_fill2","modI":0,"q":"DNA热变性时A260______。","a":"升高","e":"增色效应。"},{"id":"bc12_fill3","modI":0,"q":"Southern检测______，Northern检测______。","a":"DNA；RNA","e":"Western检测蛋白。"},{"id":"bc12_fill4","modI":0,"q":"Tm是DNA______变性时的温度。","a":"50%","e":"半变性温度。"},{"id":"bc12_fill5","modI":0,"q":"限制酶通常识别______序列。","a":"回文","e":"Ⅱ型限制酶识别回文序列。"}],"term":[{"id":"bc12_term1","modI":0,"term":"Tm","def":"DNA双螺旋失去一半时的温度，即50%变性温度。","e":"GC高、盐高使Tm升高。"},{"id":"bc12_term2","modI":0,"term":"增色效应","def":"DNA变性后260nm紫外吸收升高的现象。","e":"碱基由堆积变为暴露。"},{"id":"bc12_term3","modI":0,"term":"减色效应","def":"变性DNA复性后260nm吸收降低的现象。","e":"碱基重新堆积。"},{"id":"bc12_term4","modI":0,"term":"Cot1/2","def":"复性一半时的Cot值，反映序列复杂度。","e":"重复序列Cot1/2小，单拷贝大。"},{"id":"bc12_term5","modI":0,"term":"Southern印迹","def":"DNA电泳、变性、转膜后用探针杂交检测特定DNA。","e":"检测DNA。"},{"id":"bc12_term6","modI":0,"term":"Northern印迹","def":"RNA电泳、转膜后用探针杂交检测特定RNA。","e":"检测RNA表达。"},{"id":"bc12_term7","modI":0,"term":"Western印迹","def":"蛋白电泳、转膜后用抗体检测特定蛋白。","e":"检测蛋白，不是核酸杂交。"},{"id":"bc12_term8","modI":0,"term":"限制性内切酶","def":"识别特定DNA序列并在固定位置切割的内切酶。","e":"Ⅱ型酶识别回文序列。"}],"short":[{"id":"bc12_short_1","modI":0,"q":"为什么 DNA 比 RNA 不易被碱水解?","a":"RNA 的磷酸酯键易被碱水解产生核昔酸, 是因为 RNA 的核糖上有 2’-OH 基, 在碱作用下形成磷酸三酯。 磅酸三酯极不稳定，随即分解,产生核苷 2,3'-环磷酸酯。该环磷酸酯继续水解产生 2-核苷酸和 3-核昔酸。DNA 的脱氧核糖无 2-OH 基，不能形成碱水解的中间产物，故对碱有一定抗性。","kps":"RNA 2′-OH；碱水解成2′,3′-环磷酸；DNA无2′-OH","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第12章笔记","e":"RNA核糖有2′-OH，碱中形成2′,3′-环磷酸中间物，磷酸二酯键易被水解；DNA是脱氧核糖，无2′-OH，不能形成该中间物，故抗碱。"},{"id":"bc12_short_2","modI":0,"q":"试述核酸酶的种类和分类依据。","a":"核酸酶的种类和分类依据如下: (1) 按底物专一性分类 已作用于核糖核酸的称为核糖核酸酶; 名作用于脱氧核糖核酸的称为脱氧核糖核酸酶。 (2) 按对底物作用的方式分类 名核酸内切酶，内切酶的作用点在多核苷酸链的内部; @@核酸外切酶，外切酶的作用点从多核昔酸链的末端开始，逐个地将核苷酸切下，从而对核酸进行降解。 (3) 按磷酸二酯键断裂的方式分类 在 3-OH 与磷酸基之间断裂，其产物是 5'- BERR AT RR EAR: @在 5-OH 与磷酸基之间断裂，其产物为 3磷酸核苷酸或寡核苷酸。 (4) 其他分类标准 包对底物二级结构的专一性: a. SUE, (FFP UE AR: b.，单链酶，作用于单链。 名核酸外切酶作用的方向性: a. 3人一5'核酸外切酶， b. 5人一3'核酸外切酶。 @@对磷酸二酯键两侧的碱基有无选择性等。","kps":"底物：RNase/DNase；内切/外切；3′/5′断裂；单/双链；方向性","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第12章笔记","e":"核酸酶按底物分RNase、DNase；按作用位置分内切酶、外切酶；按磷酸二酯键断裂方式分3′-OH/5′-磷酸或5′-OH/3′-磷酸产物；还可按单/双链专一性、外切方向（3′→5′或5′→3′）分类。"},{"id":"bc12_short_3","modI":0,"q":"为什么说碱基、核苷和核昔酸是兼性离子? 是否它们都是兼性离子?","a":"〈1) 由于喀啶和味叭化合物杂环中的氮以及各取代基具有结合和释放质子的能力，所以这些物质既有碱 性解离又有酸性解离的性质，所以说，碱基是兼性离子。 (2) 核昔和核昔酸的碱基与游离碱基的解离性质相近，所以它们也是兼性离子。","kps":"杂环N可结合/释放质子；碱基、核苷、核苷酸均兼性","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第12章笔记","e":"碱基杂环上的N及取代基既能结合又能释放质子，故为兼性离子；核苷、核苷酸保留碱基解离性质，也通常为兼性离子。但并非所有pH下都带双电荷，净电荷随pH变化。"},{"id":"bc12_short_4","modI":0,"q":"5'-鸟苷酸的 PK’) 为 0.7，pK' WN 2.4, pK 为 6.1，pK'4 为 9.4，这些 pK各代表什么基团的解离常数? 其 等电点 〈pI) 是多少?","a":"pPK' 为第一个磷酸基的解离常数，pK' 为含氮环上=NH-_ -上的解离常数，pK': 为第二个磷酸基的解离 常数，pK'4 为含氛环上一NH 的解离常数。其等电点为 pI王 (PK'十pK'2 ) /2= (0.7+2.4) /2=1.6","kps":"pK1=第一磷酸；pK2=环N；pK3=第二磷酸；pK4=环NH；pI=(pK1+pK2)/2","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第12章笔记","e":"5′-鸟苷酸四个pK：pK1≈0.7为第一个磷酸基，pK2≈2.4为含氮环上=NH—，pK3≈6.1为第二个磷酸基，pK4≈9.4为环上—NH。等电点取等电点两侧的pK平均：pI=(0.7+2.4)/2≈1.6。"},{"id":"bc12_short_5","modI":0,"q":"为什么 DNA 酸碱滴定的正向曲线和反向曲线有显著的不同?","a":"DNA 酸碱进行反向滴定时的曲线和正向滴定曲线显著不同。是因为开始滴定时，没有酸碱基团解离， 非缓冲区较宽, 在 pH4.5一11.0 之间; 而在反向滴定中非缓冲区只存在于 pH6一9 之间。这就是说, 当最初的 DNA 溶液超过 pH4.5 和 pH11.0 时即迅速释放出酸碱基团参与 pH2.0一6.0 和 pH9.0一12.0 范围的滴定。","kps":"正/反滴定路径不同；滞后/构象变化；非缓冲区宽度不同","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第12章笔记","e":"DNA正滴与反滴曲线不同，是因滴定过程中构象/解离状态有滞后：正向开始非缓冲区宽（pH4.5—11），反向非缓冲区窄（pH6—9）；DNA在极端pH会发生变性/构象改变，使可滴定基团暴露不同，因此不是完全可逆的简单酸碱滴定。"},{"id":"bc12_short_6","modI":0,"q":"有一纯的质粒 DNA 溶液，共 0.5mL，取少量稀释 100 倍后测得 Azeo 为 0.330，计算此溶液共有 DNA 多 少微克? CERI DNAs (P) 为 6600，lmol 磷 DNA 平均为 310g)","a":"已知 Aaeo为 0.330，s (P) 为 6600，则稀释后的磷 DNA 溶液的浓度为 c一Aneo/ (e (P) XL) =0.33/6600=5 X 10 “mol/L 稀释液中磷 DNA [SERB VX BORE AEX c=0.5 X10 *X 100X0.5X 10 °=2.5X 10 “mol 己知 Imol # DNA 平均为 310g，所以浴液共有 DNA 的量为 310g mol 'X2.5X 10 ° mol=775pg","kps":"A260/ε=c；稀释100倍；n=cV；×310","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第12章笔记","e":"A260=0.330，ε(P)=6600，则稀释液磷浓度c=A/ε=0.330/6600=5×10^-5 mol/L。原液0.5 mL稀释100倍，总物质的量=5×10^-5×100×0.5×10^-3=2.5×10^-6 mol。DNA每mol磷平均310 g，质量=310×2.5×10^-6≈775 µg。易错：稀释倍数和体积单位。"},{"id":"bc12_short_7","modI":0,"q":"何谓增色效应? 何谓减色效应?","a":"(1) 增色效应是指与天然 DNA 相比，变性 DNA 双螺旋破坏，碱基充分外露，使得紫外吸收增加的现 象。 (2) 减色效应是指复性后紫外吸收值降低的现象。","kps":"变性→增色；复性→减色","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第12章笔记","e":"增色效应：DNA变性后双螺旋破坏，碱基由堆积变为暴露，260 nm紫外吸收升高。减色效应：变性DNA复性重新堆积，紫外吸收降低。可用A260监测变性/复性。"},{"id":"bc12_short_8","modI":0,"q":"肺炎球菌 DNA 的 G+C 含量为 40%，在 0.1ImoyL 盐溶液中其 Tw值是多少?","a":"通常把加热变性使 DNA 的双螺旋结构失去一半时的温度称为该 DNA 的熔点或溶解温度，用 Tw表示。 测定 Ta值，可以推算出 DNA 的碱基的百分组成。 其经验公式为 Ty=81.5°C+16.6 (lg[Na]) +0.41XX¢icr BRI G+C 的含量为 40%，得出 Ta一81.3'C。","kps":"Tm=81.5+16.6lg[Na+]+0.41(%GC)","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第12章笔记","e":"Tm经验式：Tm=81.5+16.6lg[Na+]+0.41(%G+C)。[Na+]=0.1 mol/L，lg0.1=−1，%GC=40：Tm≈81.5−16.6+16.4=81.3℃。GC含量越高、盐浓度越高，Tm越高。"},{"id":"bc12_short_9","modI":0,"q":"某真核生物基因组 DNA 变性后在标准条件下〈溶液阳离子浓度 0. 18mol/L, DNA 片段大小 400bp) 复 性，测得复性曲线分为三部分，快速复性部分占总量 25%，Cotm为 0.0013; 中间部分占 30%，Cot 为 1.9; 组 慢复性部分占 45%，Cotvz 为 630，试计算此基因组高度重复、中等重复和单拷贝序列的复杂度和拷贝数。(已知 大肠杆菌 DNA KA 4.64X 10%bp, Coty 9 9)","a":"在一定条件下，复性反应的速度可以用 Coty, 来衡量。Co 为变性 DNA 复性时的初始浓度，以核苷酸的 摩尔浓度表示，t 为时间，以秒表示，Cotp 表示复性一半的 Cot 值。它对特定 DNA 分子来说是常数，其速率主 由 DNA 中重复序列的含量决定。重复序列复杂程度低，复性速率最快，其次是中等重复序列，单一序列复杂程 度高，复性速率最慢。 (1) 以大肠杆菌 DNA 的相对分子质量为基准，相对分子质量平均大小为 4.64X10\"bp/9一5.2X107bp。 C2) 其中快速复性部分为高度重复序列占总量 25%, Coty 2 为 00013，校正 Coty ,>为 23% X0.0013王3.25勾 10 +，复杂度为 3.25X10“X5.2X10:一169bp，找贝数为 630/0.0013一4.8X10;。 (3) 其中中间速度复性部分为中度重复序列占总量 30%，Cot ,> 为 1.9，校正 Cot ,>为 30%X1.9=0.37，复 杂度为 0.57X5.2X10王3.0X107bp，拷贝数为 630/1.9一331。 (4) 其中缓慢复性部分为单一序列占总量 45%, Coty ,>为 630，校正 Coty ,>为 45% X 630王283.5，复杂度为","kps":"Cot1/2∝复杂度；复杂度=Cot1/2×E.coli复杂度；拷贝数=总Cot/组分Cot","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第12章笔记","e":"复性曲线按Cot1/2分三部分：高度重复（快）、中等重复、单拷贝（慢）。复杂度∝Cot1/2；用E. coli总复杂度4.64×10^6 bp、Cot1/2=9作基准，分别乘各组分校正Cot1/2求复杂度；拷贝数=该组分总Cot1/2/复杂度。题给快速、中间、慢速三部分，分别算高度重复、中等重复、单拷贝。"},{"id":"bc12_short_10","modI":0,"q":"5X5.2X105一1.47X108bp，找贝数为 1 。 LL. 核酸杂交的分子基础是什么?x 有哪些应用价值?","a":"C1) 核酸分子杂交是指不同来源的具有互补序列的两条核酸单链在一定条件下按照碱基互补配对的原则 形成双链的过程.可以是 DNA-DNA, DNA-RNA, RNA-RNA.。 其分子基础就是基于核酸分子的变性和复性原理。 (2) 应用: 包检测待定生物有机体之间是否存在亲缘关系; @@用来揭示核酸片段中某一特定基因的存在与否、拷贝数及表达丰度。","kps":"变性/复性；碱基互补；亲缘关系/基因检测/表达","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第12章笔记","e":"核酸杂交的分子基础是变性-复性：两条互补单链在适当条件下按A-T/U、G-C配对形成双链。应用：检测物种亲缘关系、基因存在与拷贝数、表达丰度、Southern/Northern、芯片和诊断。"},{"id":"bc12_short_11","modI":0,"q":"什么是 Southern 印迹法? 什么是 Northern 印迹法?","a":"(1) Southern 印迹法: 由 E.M.Southern 于 1975 年建立，将变性 DNA 从电泳凝胶通过毛细管作用转移 到纤维素膜等固相介质上，然后进行 DNA 杂交的操作过程。 (2) Northern 印迹法: MPR RNA 印迹技术，按以上方法的同样原理建立起来的 RNA 转移的方法，将变形 凝胶电泳分开的 RNA 转移到硝酸纤维素膜上，与放射性同位素标记的单链 DNA 或 RNA 探针杂交，检测特异 RNA.","kps":"Southern=DNA；Northern=RNA；转膜+探针杂交","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第12章笔记","e":"Southern印迹：DNA经电泳分离、变性、转膜，用DNA探针杂交检测特定DNA片段。Northern印迹：RNA经电泳、转膜，用探针检测特定RNA表达。区别在核酸类型和样品处理。"},{"id":"bc12_short_12","modI":0,"q":"G+C 2 EN 40%1K) DNA 其密度为多少?","a":"按照计算公式 p=1.660+0.00098 (%G+C) g/cm 得 p=1.660+0.00098 X 一1.699g/cm 故其密度为 1.699g/cm。 14， 比较蔗糖密度梯度超离心与氯化钨密度梯度超离心的异同。 答: CL) 相同之处: 都属于密度梯度离心，是用一定的介质在离心管内形成一不连续的密度梯度，将待测物 混悬液或匀浆置于介质的项部，通过重力或离心力场的作用使待测样品分层分离。 (2) 不同之处;蔗糖密度梯度超离心依据的原理是沉降速率离心，使用的介质为蔗糖，莽糖水溶性大，人性 质稳定，渗透压高，价格低康容易制备，是实验室常用的用于细胞器、病毒、RNA 分离的梯度材料，但由于有 较大的渗透压,不宜用于细胞的分离;氯化钨密度梯度超离心依据的原理是沉降平衡离心, 使用的介质为氯化钨， 氯化钨是一种离子型介质、水溶性大，由于它是重金属盐类，在离心时形成的梯度有较好的分辩率，被广泛用于 DNA、质粒、病毒和脂蛋白的分离，但分离慢，价格贵。","kps":"ρ=1.660+0.00098(%GC)；GC40→1.699","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第12章笔记","e":"DNA密度经验式ρ=1.660+0.00098×(%G+C)。%GC=40，ρ=1.660+0.0392=1.699 g/cm³。GC含量越高，密度越大。"}],"calc":[{"id":"bc12_calc1","modI":0,"q":"dsDNA溶液A260=0.5，DNA浓度约多少？","a":"25 μg/mL","e":"dsDNA A260=1≈50 μg/mL；0.5×50=25 μg/mL。"},{"id":"bc12_calc2","modI":0,"q":"RNA溶液A260=0.4，浓度约多少？","a":"16 μg/mL","e":"RNA A260=1≈40 μg/mL；0.4×40=16 μg/mL。"},{"id":"bc12_calc3","modI":0,"q":"0.5mL原液稀释100倍后A260=0.330，ε(P)=6600，求DNA质量。","a":"约775 μg","e":"c=A/ε=0.330/6600=5×10^-5 mol/L；总磷=5×10^-5×100×0.5×10^-3=2.5×10^-6 mol；×310g/mol≈775μg。"},{"id":"bc12_calc4","modI":0,"q":"[Na+]=0.1mol/L、GC=40%，Tm约多少？","a":"约81.3℃","e":"Tm=81.5+16.6lg0.1+0.41×40=81.5−16.6+16.4≈81.3℃。"},{"id":"bc12_calc5","modI":0,"q":"GC=40%的DNA密度约多少？","a":"1.699 g/cm³","e":"ρ=1.660+0.00098×40=1.699 g/cm³。"},{"id":"bc12_calc6","modI":0,"q":"A260/A280=1.6说明什么？","a":"可能有蛋白污染","e":"纯DNA约1.8；蛋白在280nm吸收，污染使比值下降。"}],"preview":{"main":"bc12共80页。先AI主讲10页，再图卡/计算，最后做题。","questions":["RNA为什么易碱解？","A260/A280意义？","Southern/Northern/Western区别？"]},"toc":[{"title":"一、核酸水解","pages":"14页","start":0,"end":14,"items":[{"title":"酸/碱/酶水解","start":0,"end":14}]},{"title":"二、限制酶与解离","pages":"9页","start":14,"end":23,"items":[{"title":"限制酶/碱基解离","start":14,"end":23}]},{"title":"三、紫外吸收","pages":"5页","start":23,"end":28,"items":[{"title":"A260/纯度/定量","start":23,"end":28}]},{"title":"四、变性复性杂交","pages":"15页","start":28,"end":43,"items":[{"title":"变性/Tm/Cot/杂交","start":28,"end":43}]},{"title":"AI主讲/精读/过程","pages":"18页","start":43,"end":61},{"title":"变式/图卡/支持/计算","pages":"19页","start":61,"end":80}],"exerciseTitle":"📝 第12章核酸性质与方法 · 网页题","exercises":[{"id":"bc12_ex1","no":1,"type":"选择","q":"在 DNA 分子中，腺嘎叭是 20%，则鸟嗓叭是多少? 〈 ) [上海交通大学 2017 研] A. 20% B. 30% C. 40% D. 50% E. 35%","analysis":"A=T=20%，G+C=60%，G=C=30%。","answer":"B","oe":["A错误：A=20%，T=20%。","B正确：A=T=20%，G+C=60%，G=C=30%。","C错误：G不是40%。","D错误：G不是50%。","E错误：G不是35%。"],"slide":43,"slideTitle":"AI主讲1：核酸水解总览","kp":"","kpId":"bc12_s0_43"},{"id":"bc12_ex2","no":2,"type":"选择","q":"将 RNA 转移到硝酸纤维素膜上，进行分子杂交的技术叫〈 )。[清华大学 2001 研] A. Southern 杂交法 B. Northern 杂交法 C.  D. Western 杂交法","analysis":"Northern检测RNA。","answer":"B","oe":["A错误：Southern检测DNA。","B正确：Northern检测RNA。","C错误：不是核酸杂交。","D错误：Western检测蛋白。"],"slide":43,"slideTitle":"AI主讲1：核酸水解总览","kp":"","kpId":"bc12_s0_43"},{"id":"bc12_ex3","no":3,"type":"选择","q":"DNA 受热变性时，出现的现象是〈 )。[全国西医综合 2005 研] A. SRT IR G B. 在 260nm 波长处的吸光度增高 C. 碱基对以共价键连接 D. 溶液黏度增加","analysis":"变性后碱基暴露，A260升高。","answer":"B","oe":["A错误：变性不破坏共价键。","B正确：变性碱基暴露，A260升高。","C错误：碱基对靠氢键，不共价。","D错误：变性黏度下降。"],"slide":43,"slideTitle":"AI主讲1：核酸水解总览","kp":"","kpId":"bc12_s0_43"},{"id":"bc12_ex4","no":4,"type":"选择","q":"(Sik) 一溶液含有 PCR 扩增后的 DNA 产物，在 95C加热 10min，然后冰上快速冷却，以下变化将发生 ( )。[中科院水生生物研究所 2007 WF] A. 该溶液在 260nm 的吸光度将增加 D.  E. 以上的变化都不会有","analysis":"加热变性→增色效应。","answer":"A","oe":["A正确：加热变性后A260升高。","B错误：不是降低。","C错误：不是不变。","D错误：260吸收会变化。","E错误：有明显变化。"],"slide":43,"slideTitle":"AI主讲1：核酸水解总览","kp":"","kpId":"bc12_s0_43"},{"id":"bc12_ex5","no":5,"type":"选择","q":"RNA比DNA更容易被碱水解，主要原因是？ A. RNA有2′-OH B. RNA有2′-H C. RNA是单链 D. RNA含U","analysis":"RNA核糖2′-OH参与形成2′,3′-环磷酸中间物，使磷酸二酯键易水解；DNA无2′-OH，较抗碱。","answer":"A","oe":["正确：2′-OH参与碱解中间物。","错误：DNA才是2′-H。","错误：单链不是主因。","错误：U不决定碱解。"],"slide":43,"slideTitle":"AI主讲1：核酸水解总览","kp":"","kpId":"bc12_s0_43"},{"id":"bc12_ex6","no":6,"type":"选择","q":"酸水解核酸主要产生？ A. 无嘌呤核酸 B. 无嘧啶核酸 C. 单核苷酸 D. 核苷","analysis":"酸水解主要断裂嘌呤糖苷键，生成无嘌呤核酸。","answer":"A","oe":["正确：酸水解主要脱嘌呤。","错误：不是无嘧啶核酸。","错误：产物不是单核苷酸为主。","错误：不是核苷。"],"slide":43,"slideTitle":"AI主讲1：核酸水解总览","kp":"","kpId":"bc12_s0_43"},{"id":"bc12_ex7","no":7,"type":"选择","q":"限制性内切酶通常识别？ A. 回文序列 B. polyA C. 启动子 D. 终止子","analysis":"Ⅱ型限制酶识别特定回文序列并在固定位置切割。","answer":"A","oe":["正确：识别回文序列。","错误：polyA不是识别序列。","错误：启动子是转录调控。","错误：终止子不是限制酶位点。"],"slide":43,"slideTitle":"AI主讲1：核酸水解总览","kp":"","kpId":"bc12_s0_43"},{"id":"bc12_ex8","no":8,"type":"选择","q":"核酸260nm紫外吸收主要来自？ A. 碱基共轭双键 B. 磷酸二酯键 C. 糖苷键 D. 肽键","analysis":"嘌呤/嘧啶的共轭双键产生260nm吸收。","answer":"A","oe":["正确：碱基共轭双键。","错误：磷酸二酯键不产生260吸收。","错误：糖苷键不是主要吸收。","错误：肽键在蛋白。"],"slide":43,"slideTitle":"AI主讲1：核酸水解总览","kp":"","kpId":"bc12_s0_43"},{"id":"bc12_ex9","no":9,"type":"选择","q":"双链DNA A260=1约相当于多少浓度？ A. 50 μg/mL B. 1 μg/mL C. 500 μg/mL D. 5 mg/mL","analysis":"dsDNA A260=1≈50 μg/mL。","answer":"A","oe":["正确：50 μg/mL。","错误：太小。","错误：太大。","错误：单位不对。"],"slide":43,"slideTitle":"AI主讲1：核酸水解总览","kp":"","kpId":"bc12_s0_43"},{"id":"bc12_ex10","no":10,"type":"选择","q":"DNA的A260/A280约为？ A. 1.8 B. 0.5 C. 3.0 D. 0","analysis":"纯DNA约1.8；RNA约2.0；蛋白污染使比值下降。","answer":"A","oe":["正确：约1.8。","错误：0.5表示严重蛋白污染。","错误：3.0不是纯DNA。","错误：0不可能。"],"slide":43,"slideTitle":"AI主讲1：核酸水解总览","kp":"","kpId":"bc12_s0_43"},{"id":"bc12_ex11","no":11,"type":"选择","q":"DNA热变性时？ A. A260升高 B. A260降低 C. 共价键断裂 D. 黏度升高","analysis":"双螺旋解开，碱基暴露，A260升高（增色效应）。","answer":"A","oe":["正确：A260升高。","错误：不是降低。","错误：共价键不断。","错误：黏度下降。"],"slide":43,"slideTitle":"AI主讲1：核酸水解总览","kp":"","kpId":"bc12_s0_43"},{"id":"bc12_ex12","no":12,"type":"选择","q":"Tm是指？ A. 50%变性时的温度 B. 完全变性温度 C. 复性温度 D. 退火温度","analysis":"Tm为双螺旋失去一半时的温度。","answer":"A","oe":["正确：50%变性温度。","错误：不是完全变性。","错误：不是复性温度。","错误：退火是杂交条件。"],"slide":43,"slideTitle":"AI主讲1：核酸水解总览","kp":"","kpId":"bc12_s0_43"},{"id":"bc12_ex13","no":13,"type":"选择","q":"GC含量升高时Tm通常？ A. 升高 B. 降低 C. 不变 D. 变为0","analysis":"G-C有3个氢键，GC高更稳定，Tm升高。","answer":"A","oe":["正确：GC高Tm高。","错误：AT高Tm低。","错误：会变。","错误：不会为0。"],"slide":43,"slideTitle":"AI主讲1：核酸水解总览","kp":"","kpId":"bc12_s0_43"},{"id":"bc12_ex14","no":14,"type":"选择","q":"复性时紫外吸收？ A. 降低 B. 升高 C. 不变 D. 消失","analysis":"复性碱基重新堆积，A260降低（减色效应）。","answer":"A","oe":["正确：复性A260降低。","错误：升高是变性。","错误：会变。","错误：不会消失。"],"slide":43,"slideTitle":"AI主讲1：核酸水解总览","kp":"","kpId":"bc12_s0_43"},{"id":"bc12_ex15","no":15,"type":"选择","q":"Cot1/2较小说明？ A. 重复序列多 B. 单拷贝多 C. 复杂度高 D. 变性难","analysis":"重复序列复性快，Cot1/2小。","answer":"A","oe":["正确：重复序列多。","错误：单拷贝Cot1/2大。","错误：复杂度高复性慢。","错误：不是变性难。"],"slide":43,"slideTitle":"AI主讲1：核酸水解总览","kp":"","kpId":"bc12_s0_43"},{"id":"bc12_ex16","no":16,"type":"选择","q":"Southern印迹检测？ A. DNA B. RNA C. 蛋白 D. 脂质","analysis":"Southern检测DNA，Northern检测RNA，Western检测蛋白。","answer":"A","oe":["正确：DNA。","错误：RNA是Northern。","错误：蛋白是Western。","错误：脂质不是。"],"slide":43,"slideTitle":"AI主讲1：核酸水解总览","kp":"","kpId":"bc12_s0_43"},{"id":"bc12_ex17","no":17,"type":"选择","q":"Northern印迹检测？ A. RNA B. DNA C. 蛋白 D. 糖","analysis":"Northern检测RNA。","answer":"A","oe":["正确：RNA。","错误：DNA是Southern。","错误：蛋白是Western。","错误：糖不是。"],"slide":43,"slideTitle":"AI主讲1：核酸水解总览","kp":"","kpId":"bc12_s0_43"},{"id":"bc12_ex18","no":18,"type":"选择","q":"Western印迹检测？ A. 蛋白 B. DNA C. RNA D. 脂质","analysis":"Western用抗体检测蛋白。","answer":"A","oe":["正确：蛋白。","错误：DNA是Southern。","错误：RNA是Northern。","错误：脂质不是。"],"slide":43,"slideTitle":"AI主讲1：核酸水解总览","kp":"","kpId":"bc12_s0_43"},{"id":"bc12_ex19","no":19,"type":"选择","q":"DNA密度随GC含量升高？ A. 升高 B. 降低 C. 不变 D. 先升后降","analysis":"ρ=1.660+0.00098(%GC)，GC↑密度↑。","answer":"A","oe":["正确：GC高密度高。","错误：不是降低。","错误：会变。","错误：不是先升后降。"],"slide":43,"slideTitle":"AI主讲1：核酸水解总览","kp":"","kpId":"bc12_s0_43"},{"id":"bc12_ex20","no":20,"type":"简答","q":"为什么 DNA 比 RNA 不易被碱水解?","analysis":"RNA核糖有2′-OH，碱中形成2′,3′-环磷酸中间物，磷酸二酯键易被水解；DNA是脱氧核糖，无2′-OH，不能形成该中间物，故抗碱。","answer":"RNA 的磷酸酯键易被碱水解产生核昔酸, 是因为 RNA 的核糖上有 2’-OH 基, 在碱作用下形成磷酸三酯。 磅酸三酯极不稳定，随即分解,产生核苷 2,3'-环磷酸酯。该环磷酸酯继续水解产生 2-核苷酸和 3-核昔酸。DNA 的脱氧核糖无 2-OH 基，不能形成碱水解的中间产物，故对碱有一定抗性。","slide":43,"slideTitle":"AI主讲1：核酸水解总览","kp":"","kpId":"bc12_s0_43"},{"id":"bc12_ex21","no":21,"type":"简答","q":"试述核酸酶的种类和分类依据。","analysis":"核酸酶按底物分RNase、DNase；按作用位置分内切酶、外切酶；按磷酸二酯键断裂方式分3′-OH/5′-磷酸或5′-OH/3′-磷酸产物；还可按单/双链专一性、外切方向（3′→5′或5′→3′）分类。","answer":"核酸酶的种类和分类依据如下: (1) 按底物专一性分类 已作用于核糖核酸的称为核糖核酸酶; 名作用于脱氧核糖核酸的称为脱氧核糖核酸酶。 (2) 按对底物作用的方式分类 名核酸内切酶，内切酶的作用点在多核苷酸链的内部; @@核酸外切酶，外切酶的作用点从多核昔酸链的末端开始，逐个地将核苷酸切下，从而对核酸进行降解。 (3) 按磷酸二酯键断裂的方式分类 在 3-OH 与磷酸基之间断裂，其产物是 5'- BERR AT RR EAR: @在 5-OH 与磷酸基之间断裂，其产物为 3磷酸核苷酸或寡核苷酸。 (4) 其他分类标准 包对底物二级结构的专一性: a. SUE, (FFP UE AR: b.，单链酶，作用于单链。 名核酸外切酶作用的方向性: a. 3人一5'核酸外切酶， b. 5人一3'核酸外切酶。 @@对磷酸二酯键两侧的碱基有无选择性等。","slide":43,"slideTitle":"AI主讲1：核酸水解总览","kp":"","kpId":"bc12_s0_43"},{"id":"bc12_ex22","no":22,"type":"简答","q":"为什么说碱基、核苷和核昔酸是兼性离子? 是否它们都是兼性离子?","analysis":"碱基杂环上的N及取代基既能结合又能释放质子，故为兼性离子；核苷、核苷酸保留碱基解离性质，也通常为兼性离子。但并非所有pH下都带双电荷，净电荷随pH变化。","answer":"〈1) 由于喀啶和味叭化合物杂环中的氮以及各取代基具有结合和释放质子的能力，所以这些物质既有碱 性解离又有酸性解离的性质，所以说，碱基是兼性离子。 (2) 核昔和核昔酸的碱基与游离碱基的解离性质相近，所以它们也是兼性离子。","slide":43,"slideTitle":"AI主讲1：核酸水解总览","kp":"","kpId":"bc12_s0_43"},{"id":"bc12_ex23","no":23,"type":"简答","q":"5'-鸟苷酸的 PK’) 为 0.7，pK' WN 2.4, pK 为 6.1，pK'4 为 9.4，这些 pK各代表什么基团的解离常数? 其 等电点 〈pI) 是多少?","analysis":"5′-鸟苷酸四个pK：pK1≈0.7为第一个磷酸基，pK2≈2.4为含氮环上=NH—，pK3≈6.1为第二个磷酸基，pK4≈9.4为环上—NH。等电点取等电点两侧的pK平均：pI=(0.7+2.4)/2≈1.6。","answer":"pPK' 为第一个磷酸基的解离常数，pK' 为含氮环上=NH-_ -上的解离常数，pK': 为第二个磷酸基的解离 常数，pK'4 为含氛环上一NH 的解离常数。其等电点为 pI王 (PK'十pK'2 ) /2= (0.7+2.4) /2=1.6","slide":43,"slideTitle":"AI主讲1：核酸水解总览","kp":"","kpId":"bc12_s0_43"},{"id":"bc12_ex24","no":24,"type":"简答","q":"为什么 DNA 酸碱滴定的正向曲线和反向曲线有显著的不同?","analysis":"DNA正滴与反滴曲线不同，是因滴定过程中构象/解离状态有滞后：正向开始非缓冲区宽（pH4.5—11），反向非缓冲区窄（pH6—9）；DNA在极端pH会发生变性/构象改变，使可滴定基团暴露不同，因此不是完全可逆的简单酸碱滴定。","answer":"DNA 酸碱进行反向滴定时的曲线和正向滴定曲线显著不同。是因为开始滴定时，没有酸碱基团解离， 非缓冲区较宽, 在 pH4.5一11.0 之间; 而在反向滴定中非缓冲区只存在于 pH6一9 之间。这就是说, 当最初的 DNA 溶液超过 pH4.5 和 pH11.0 时即迅速释放出酸碱基团参与 pH2.0一6.0 和 pH9.0一12.0 范围的滴定。","slide":43,"slideTitle":"AI主讲1：核酸水解总览","kp":"","kpId":"bc12_s0_43"},{"id":"bc12_ex25","no":25,"type":"简答","q":"有一纯的质粒 DNA 溶液，共 0.5mL，取少量稀释 100 倍后测得 Azeo 为 0.330，计算此溶液共有 DNA 多 少微克? CERI DNAs (P) 为 6600，lmol 磷 DNA 平均为 310g)","analysis":"A260=0.330，ε(P)=6600，则稀释液磷浓度c=A/ε=0.330/6600=5×10^-5 mol/L。原液0.5 mL稀释100倍，总物质的量=5×10^-5×100×0.5×10^-3=2.5×10^-6 mol。DNA每mol磷平均310 g，质量=310×2.5×10^-6≈775 µg。易错：稀释倍数和体积单位。","answer":"已知 Aaeo为 0.330，s (P) 为 6600，则稀释后的磷 DNA 溶液的浓度为 c一Aneo/ (e (P) XL) =0.33/6600=5 X 10 “mol/L 稀释液中磷 DNA [SERB VX BORE AEX c=0.5 X10 *X 100X0.5X 10 °=2.5X 10 “mol 己知 Imol # DNA 平均为 310g，所以浴液共有 DNA 的量为 310g mol 'X2.5X 10 ° mol=775pg","slide":43,"slideTitle":"AI主讲1：核酸水解总览","kp":"","kpId":"bc12_s0_43"},{"id":"bc12_ex26","no":26,"type":"简答","q":"何谓增色效应? 何谓减色效应?","analysis":"增色效应：DNA变性后双螺旋破坏，碱基由堆积变为暴露，260 nm紫外吸收升高。减色效应：变性DNA复性重新堆积，紫外吸收降低。可用A260监测变性/复性。","answer":"(1) 增色效应是指与天然 DNA 相比，变性 DNA 双螺旋破坏，碱基充分外露，使得紫外吸收增加的现 象。 (2) 减色效应是指复性后紫外吸收值降低的现象。","slide":43,"slideTitle":"AI主讲1：核酸水解总览","kp":"","kpId":"bc12_s0_43"},{"id":"bc12_ex27","no":27,"type":"简答","q":"肺炎球菌 DNA 的 G+C 含量为 40%，在 0.1ImoyL 盐溶液中其 Tw值是多少?","analysis":"Tm经验式：Tm=81.5+16.6lg[Na+]+0.41(%G+C)。[Na+]=0.1 mol/L，lg0.1=−1，%GC=40：Tm≈81.5−16.6+16.4=81.3℃。GC含量越高、盐浓度越高，Tm越高。","answer":"通常把加热变性使 DNA 的双螺旋结构失去一半时的温度称为该 DNA 的熔点或溶解温度，用 Tw表示。 测定 Ta值，可以推算出 DNA 的碱基的百分组成。 其经验公式为 Ty=81.5°C+16.6 (lg[Na]) +0.41XX¢icr BRI G+C 的含量为 40%，得出 Ta一81.3'C。","slide":43,"slideTitle":"AI主讲1：核酸水解总览","kp":"","kpId":"bc12_s0_43"},{"id":"bc12_ex28","no":28,"type":"简答","q":"某真核生物基因组 DNA 变性后在标准条件下〈溶液阳离子浓度 0. 18mol/L, DNA 片段大小 400bp) 复 性，测得复性曲线分为三部分，快速复性部分占总量 25%，Cotm为 0.0013; 中间部分占 30%，Cot 为 1.9; 组 慢复性部分占 45%，Cotvz 为 630，试计算此基因组高度重复、中等重复和单拷贝序列的复杂度和拷贝数。(已知 大肠杆菌 DNA KA 4.64X 10%bp, Coty 9 9)","analysis":"复性曲线按Cot1/2分三部分：高度重复（快）、中等重复、单拷贝（慢）。复杂度∝Cot1/2；用E. coli总复杂度4.64×10^6 bp、Cot1/2=9作基准，分别乘各组分校正Cot1/2求复杂度；拷贝数=该组分总Cot1/2/复杂度。题给快速、中间、慢速三部分，分别算高度重复、中等重复、单拷贝。","answer":"在一定条件下，复性反应的速度可以用 Coty, 来衡量。Co 为变性 DNA 复性时的初始浓度，以核苷酸的 摩尔浓度表示，t 为时间，以秒表示，Cotp 表示复性一半的 Cot 值。它对特定 DNA 分子来说是常数，其速率主 由 DNA 中重复序列的含量决定。重复序列复杂程度低，复性速率最快，其次是中等重复序列，单一序列复杂程 度高，复性速率最慢。 (1) 以大肠杆菌 DNA 的相对分子质量为基准，相对分子质量平均大小为 4.64X10\"bp/9一5.2X107bp。 C2) 其中快速复性部分为高度重复序列占总量 25%, Coty 2 为 00013，校正 Coty ,>为 23% X0.0013王3.25勾 10 +，复杂度为 3.25X10“X5.2X10:一169bp，找贝数为 630/0.0013一4.8X10;。 (3) 其中中间速度复性部分为中度重复序列占总量 30%，Cot ,> 为 1.9，校正 Cot ,>为 30%X1.9=0.37，复 杂度为 0.57X5.2X10王3.0X107bp，拷贝数为 630/1.9一331。 (4) 其中缓慢复性部分为单一序列占总量 45%, Coty ,>为 630，校正 Coty ,>为 45% X 630王283.5，复杂度为","slide":43,"slideTitle":"AI主讲1：核酸水解总览","kp":"","kpId":"bc12_s0_43"},{"id":"bc12_ex29","no":29,"type":"简答","q":"5X5.2X105一1.47X108bp，找贝数为 1 。 LL. 核酸杂交的分子基础是什么?x 有哪些应用价值?","analysis":"核酸杂交的分子基础是变性-复性：两条互补单链在适当条件下按A-T/U、G-C配对形成双链。应用：检测物种亲缘关系、基因存在与拷贝数、表达丰度、Southern/Northern、芯片和诊断。","answer":"C1) 核酸分子杂交是指不同来源的具有互补序列的两条核酸单链在一定条件下按照碱基互补配对的原则 形成双链的过程.可以是 DNA-DNA, DNA-RNA, RNA-RNA.。 其分子基础就是基于核酸分子的变性和复性原理。 (2) 应用: 包检测待定生物有机体之间是否存在亲缘关系; @@用来揭示核酸片段中某一特定基因的存在与否、拷贝数及表达丰度。","slide":43,"slideTitle":"AI主讲1：核酸水解总览","kp":"","kpId":"bc12_s0_43"},{"id":"bc12_ex30","no":30,"type":"简答","q":"什么是 Southern 印迹法? 什么是 Northern 印迹法?","analysis":"Southern印迹：DNA经电泳分离、变性、转膜，用DNA探针杂交检测特定DNA片段。Northern印迹：RNA经电泳、转膜，用探针检测特定RNA表达。区别在核酸类型和样品处理。","answer":"(1) Southern 印迹法: 由 E.M.Southern 于 1975 年建立，将变性 DNA 从电泳凝胶通过毛细管作用转移 到纤维素膜等固相介质上，然后进行 DNA 杂交的操作过程。 (2) Northern 印迹法: MPR RNA 印迹技术，按以上方法的同样原理建立起来的 RNA 转移的方法，将变形 凝胶电泳分开的 RNA 转移到硝酸纤维素膜上，与放射性同位素标记的单链 DNA 或 RNA 探针杂交，检测特异 RNA.","slide":43,"slideTitle":"AI主讲1：核酸水解总览","kp":"","kpId":"bc12_s0_43"},{"id":"bc12_ex31","no":31,"type":"简答","q":"G+C 2 EN 40%1K) DNA 其密度为多少?","analysis":"DNA密度经验式ρ=1.660+0.00098×(%G+C)。%GC=40，ρ=1.660+0.0392=1.699 g/cm³。GC含量越高，密度越大。","answer":"按照计算公式 p=1.660+0.00098 (%G+C) g/cm 得 p=1.660+0.00098 X 一1.699g/cm 故其密度为 1.699g/cm。 14， 比较蔗糖密度梯度超离心与氯化钨密度梯度超离心的异同。 答: CL) 相同之处: 都属于密度梯度离心，是用一定的介质在离心管内形成一不连续的密度梯度，将待测物 混悬液或匀浆置于介质的项部，通过重力或离心力场的作用使待测样品分层分离。 (2) 不同之处;蔗糖密度梯度超离心依据的原理是沉降速率离心，使用的介质为蔗糖，莽糖水溶性大，人性 质稳定，渗透压高，价格低康容易制备，是实验室常用的用于细胞器、病毒、RNA 分离的梯度材料，但由于有 较大的渗透压,不宜用于细胞的分离;氯化钨密度梯度超离心依据的原理是沉降平衡离心, 使用的介质为氯化钨， 氯化钨是一种离子型介质、水溶性大，由于它是重金属盐类，在离心时形成的梯度有较好的分辩率，被广泛用于 DNA、质粒、病毒和脂蛋白的分离，但分离慢，价格贵。","slide":43,"slideTitle":"AI主讲1：核酸水解总览","kp":"","kpId":"bc12_s0_43"},{"id":"bc12_ex32","no":32,"type":"计算","q":"dsDNA溶液A260=0.5，DNA浓度约多少？","analysis":"dsDNA A260=1≈50 μg/mL；0.5×50=25 μg/mL。","answer":"25 μg/mL","slide":79,"slideTitle":"bc12 使用评估与学习建议","kp":"","kpId":"bc12_s0_79"},{"id":"bc12_ex33","no":33,"type":"计算","q":"RNA溶液A260=0.4，浓度约多少？","analysis":"RNA A260=1≈40 μg/mL；0.4×40=16 μg/mL。","answer":"16 μg/mL","slide":79,"slideTitle":"bc12 使用评估与学习建议","kp":"","kpId":"bc12_s0_79"},{"id":"bc12_ex34","no":34,"type":"计算","q":"0.5mL原液稀释100倍后A260=0.330，ε(P)=6600，求DNA质量。","analysis":"c=A/ε=0.330/6600=5×10^-5 mol/L；总磷=5×10^-5×100×0.5×10^-3=2.5×10^-6 mol；×310g/mol≈775μg。","answer":"约775 μg","slide":79,"slideTitle":"bc12 使用评估与学习建议","kp":"","kpId":"bc12_s0_79"},{"id":"bc12_ex35","no":35,"type":"计算","q":"[Na+]=0.1mol/L、GC=40%，Tm约多少？","analysis":"Tm=81.5+16.6lg0.1+0.41×40=81.5−16.6+16.4≈81.3℃。","answer":"约81.3℃","slide":79,"slideTitle":"bc12 使用评估与学习建议","kp":"","kpId":"bc12_s0_79"},{"id":"bc12_ex36","no":36,"type":"计算","q":"GC=40%的DNA密度约多少？","analysis":"ρ=1.660+0.00098×40=1.699 g/cm³。","answer":"1.699 g/cm³","slide":79,"slideTitle":"bc12 使用评估与学习建议","kp":"","kpId":"bc12_s0_79"},{"id":"bc12_ex37","no":37,"type":"计算","q":"A260/A280=1.6说明什么？","analysis":"纯DNA约1.8；蛋白在280nm吸收，污染使比值下降。","answer":"可能有蛋白污染","slide":79,"slideTitle":"bc12 使用评估与学习建议","kp":"","kpId":"bc12_s0_79"},{"id":"bc12_ex38","no":38,"type":"名词","q":"解释名词：Tm","analysis":"GC高、盐高使Tm升高。","answer":"DNA双螺旋失去一半时的温度，即50%变性温度。","slide":43,"slideTitle":"AI主讲1：核酸水解总览","kp":"","kpId":"bc12_s0_43"},{"id":"bc12_ex39","no":39,"type":"名词","q":"解释名词：增色效应","analysis":"碱基由堆积变为暴露。","answer":"DNA变性后260nm紫外吸收升高的现象。","slide":43,"slideTitle":"AI主讲1：核酸水解总览","kp":"","kpId":"bc12_s0_43"},{"id":"bc12_ex40","no":40,"type":"名词","q":"解释名词：减色效应","analysis":"碱基重新堆积。","answer":"变性DNA复性后260nm吸收降低的现象。","slide":43,"slideTitle":"AI主讲1：核酸水解总览","kp":"","kpId":"bc12_s0_43"},{"id":"bc12_ex41","no":41,"type":"名词","q":"解释名词：Cot1/2","analysis":"重复序列Cot1/2小，单拷贝大。","answer":"复性一半时的Cot值，反映序列复杂度。","slide":43,"slideTitle":"AI主讲1：核酸水解总览","kp":"","kpId":"bc12_s0_43"},{"id":"bc12_ex42","no":42,"type":"名词","q":"解释名词：Southern印迹","analysis":"检测DNA。","answer":"DNA电泳、变性、转膜后用探针杂交检测特定DNA。","slide":43,"slideTitle":"AI主讲1：核酸水解总览","kp":"","kpId":"bc12_s0_43"},{"id":"bc12_ex43","no":43,"type":"名词","q":"解释名词：Northern印迹","analysis":"检测RNA表达。","answer":"RNA电泳、转膜后用探针杂交检测特定RNA。","slide":43,"slideTitle":"AI主讲1：核酸水解总览","kp":"","kpId":"bc12_s0_43"},{"id":"bc12_ex44","no":44,"type":"名词","q":"解释名词：Western印迹","analysis":"检测蛋白，不是核酸杂交。","answer":"蛋白电泳、转膜后用抗体检测特定蛋白。","slide":43,"slideTitle":"AI主讲1：核酸水解总览","kp":"","kpId":"bc12_s0_43"},{"id":"bc12_ex45","no":45,"type":"名词","q":"解释名词：限制性内切酶","analysis":"Ⅱ型酶识别回文序列。","answer":"识别特定DNA序列并在固定位置切割的内切酶。","slide":43,"slideTitle":"AI主讲1：核酸水解总览","kp":"","kpId":"bc12_s0_43"},{"id":"bc12_ex46","no":46,"type":"判断","q":"DNA比RNA更耐碱水解。","analysis":"DNA无2′-OH，不能形成2′,3′-环磷酸中间物，较抗碱。","answer":"对","slide":43,"slideTitle":"AI主讲1：核酸水解总览","kp":"","kpId":"bc12_s0_43"},{"id":"bc12_ex47","no":47,"type":"判断","q":"DNA变性后260nm吸收降低。","analysis":"变性后碱基暴露，A260升高（增色效应）。","answer":"错","slide":43,"slideTitle":"AI主讲1：核酸水解总览","kp":"","kpId":"bc12_s0_43"},{"id":"bc12_ex48","no":48,"type":"判断","q":"GC含量越高，Tm越高。","analysis":"G-C有3个氢键，GC高更稳定。","answer":"对","slide":43,"slideTitle":"AI主讲1：核酸水解总览","kp":"","kpId":"bc12_s0_43"},{"id":"bc12_ex49","no":49,"type":"判断","q":"Southern印迹检测RNA。","analysis":"Southern检测DNA；Northern检测RNA。","answer":"错","slide":43,"slideTitle":"AI主讲1：核酸水解总览","kp":"","kpId":"bc12_s0_43"},{"id":"bc12_ex51","no":51,"type":"选择","q":"DNA和RNA共有的碱基是？ A. A、G、C B. A、G、T C. A、G、U D. T、U、C","analysis":"DNA为A/G/C/T，RNA为A/G/C/U，共有A、G、C。","answer":"A","oe":["正确：A、G、C共有。","错误：T只在DNA。","错误：U只在RNA。","错误：T/U不共有。"],"slide":43,"slideTitle":"AI主讲1：核酸水解总览","kp":"","kpId":"bc12_s0_43"}]};